// Do not hand-edit; change the .py file and build again. Standards codes are checked against data/standards.js.
// Fields: id, std (Alabama code), part (letter), q, a, lvl (1 on-ramp, 2 on level, 3 stretch), choices, also (other right answers), steps (Vault Raid step help).
export default {"cls": "8th","label": "8th Grade","items": [{"id": "8.1-01","std": "8.1","q": "Is √50 rational or irrational?","a": "Irrational","lvl": 1,"choices": ["Rational","Irrational"],"steps": ["Is 50 a perfect square? Check: 7² = 49 and 8² = 64.","The square root of a number that isn't a perfect square never ends or repeats. What kind of number is that?"]},{"id": "8.1-02","std": "8.1","q": "Is 0.125 rational or irrational?","a": "Rational","lvl": 1,"choices": ["Rational","Irrational"],"steps": ["A rational number can be written as a fraction.","0.125 ends. Write it as {125/1000}. Can every ending decimal be a fraction?"]},{"id": "8.1-03","std": "8.1","q": "Is π rational or irrational?","a": "Irrational","lvl": 1,"choices": ["Rational","Irrational"],"steps": ["π = 3.14159… The digits keep going with no pattern.","A decimal that never ends or repeats can't be written as a fraction. What kind of number is that?"]},{"id": "8.1-04","std": "8.1","q": "Is √81 rational or irrational?","a": "Rational (√81 = 9)","lvl": 1,"choices": ["Rational (√81 = 9)","Irrational"],"steps": ["Is 81 a perfect square? What number times itself is 81?","If the square root is a whole number, it can be written as a fraction."]},{"id": "8.1-05","std": "8.1","q": "Does the decimal for {5/8} terminate or repeat?","a": "Terminates (0.625)","lvl": 1,"part": "a","choices": ["Terminates (0.625)","Repeats"],"steps": ["A fraction means divide: 5 ÷ 8.","Keep dividing. Does it end with a remainder of 0, or does a digit keep repeating?"]},{"id": "8.1-06","std": "8.1","q": "Write {4/9} as a decimal.","a": "0.444… (repeating 4)","lvl": 2,"part": "a","also": ["0.4 repeating","0.444..."],"steps": ["A fraction means divide: 4 ÷ 9.","Keep dividing for a few places. What digit keeps coming back?"]},{"id": "8.1-07","std": "8.1","q": "Write 0.777… (7 repeating) as a fraction.","a": "{7/9}","lvl": 2,"part": "b","steps": ["Let x = 0.777… Then 10x = 7.777…","Subtract: 10x − x = 7.777… − 0.777…, so 9x = 7.","Divide both sides by 9."]},{"id": "8.1-08","std": "8.1","q": "Write 0.272727… (27 repeating) as a fraction in simplest form.","a": "{3/11}","lvl": 2,"part": "b","steps": ["Two digits repeat, so multiply by 100. Let x = 0.2727… Then 100x = 27.2727…","Subtract: 100x − x = 27, so 99x = 27.","Divide by 99, then simplify the fraction."]},{"id": "8.1-09","std": "8.1","q": "Write 0.1666… (6 repeating) as a fraction in simplest form.","a": "{1/6}","lvl": 3,"part": "b","steps": ["Let x = 0.1666… Then 10x = 1.666… and 100x = 16.666…","Subtract: 100x − 10x = 16.666… − 1.666…, so 90x = 15.","Divide by 90, then simplify the fraction."]},{"id": "8.1-10","std": "8.1","q": "Write 1.333… (3 repeating) as a fraction.","a": "{4/3}","lvl": 3,"part": "b","also": ["1{1/3}"],"steps": ["Let x = 1.333… Then 10x = 13.333…","Subtract: 10x − x = 12, so 9x = 12.","Divide by 9, then simplify the fraction."]},{"id": "8.1-11","std": "8.1","q": "Which number is irrational? A. −{2/3}  B. 0.5  C. √7  D. √16","a": "C","lvl": 2,"choices": ["A","B","C","D"],"steps": ["Rational numbers are fractions, ending decimals, or repeating decimals.","Check each square root: is 7 a perfect square? Is 16?"]},{"id": "8.2-01","std": "8.2","q": "√30 is between which two whole numbers?","a": "5 and 6","lvl": 1,"also": ["5, 6"],"steps": ["Find the perfect squares on each side of 30: 5² = 25 and 6² = 36.","30 is between 25 and 36, so √30 is between their square roots."]},{"id": "8.2-02","std": "8.2","q": "√70 is between which two whole numbers?","a": "8 and 9","lvl": 1,"also": ["8, 9"],"steps": ["Find the perfect squares on each side of 70: 8² = 64 and 9² = 81.","70 is between 64 and 81, so √70 is between their square roots."]},{"id": "8.2-03","std": "8.2","q": "Is √40 closer to 6 or 7?","a": "6 (40 is closer to 36 than to 49)","lvl": 2,"also": ["6"],"steps": ["6² = 36 and 7² = 49.","Is 40 closer to 36 or to 49? Find each distance."]},{"id": "8.2-04","std": "8.2","q": "Estimate √20 to the nearest tenth.","a": "4.5","lvl": 2,"steps": ["4² = 16 and 5² = 25, so √20 is between 4 and 5.","Try tenths: 4.4² = 19.36 and 4.5² = 20.25.","Which one is closer to 20?"]},{"id": "8.2-05","std": "8.2","q": "Which is greater: √50 or 7.2?","a": "7.2","lvl": 2,"also": ["7.2"],"steps": ["Square both numbers so they're easy to compare: (√50)² = 50.","7.2² = 7.2 × 7.2. Which square is bigger?"]},{"id": "8.2-06","std": "8.2","q": "Order from least to greatest: √10, 3.5, π","a": "π, √10, 3.5","lvl": 3,"steps": ["Change each to a decimal: √10 is a little more than 3, since 3² = 9.","√10 ≈ 3.16, π ≈ 3.14, and 3.5 is 3.5.","Put the decimals in order from smallest to biggest."]},{"id": "8.2-07","std": "8.2","q": "Estimate √2 to the nearest tenth.","a": "1.4","lvl": 2,"steps": ["1² = 1 and 2² = 4, so √2 is between 1 and 2.","Try tenths: 1.4² = 1.96 and 1.5² = 2.25. Which is closer to 2?"]},{"id": "8.2-08","std": "8.2","q": "Between which two consecutive whole numbers is −√12?","a": "−4 and −3","lvl": 3,"also": ["−4, −3"],"steps": ["First find √12: 3² = 9 and 4² = 16, so √12 is between 3 and 4.","−√12 is the opposite, so it's between −4 and −3. Write them in order."]},{"id": "8.2-09","std": "8.2","q": "Estimate π² to the nearest whole number.","a": "10","lvl": 3,"steps": ["π is about 3.14.","π² = π × π. Multiply 3.14 × 3.14, then round to a whole number."]},{"id": "8.3-01","std": "8.3","q": "Simplify: 3² × 3⁴","a": "3⁶","lvl": 1,"also": ["729","3^6"],"steps": ["Same base, multiplying: add the exponents.","Add: 2 + 4. Keep the base 3."]},{"id": "8.3-02","std": "8.3","q": "Simplify: 5⁷ ÷ 5³","a": "5⁴","lvl": 1,"also": ["625","5^4"],"steps": ["Same base, dividing: subtract the exponents.","Subtract: 7 − 3. Keep the base 5."]},{"id": "8.3-03","std": "8.3","q": "Simplify: (2³)²","a": "2⁶","lvl": 1,"also": ["64","2^6"],"steps": ["A power of a power: multiply the exponents.","Multiply: 3 × 2. Keep the base 2."]},{"id": "8.3-04","std": "8.3","q": "Evaluate: 4⁰","a": "1","lvl": 1,"steps": ["Any number (except 0) to the zero power is the same value.","Think: 4³ ÷ 4³ = 4⁰. What is any number divided by itself?"]},{"id": "8.3-05","std": "8.3","q": "Evaluate: 2⁻³","a": "{1/8}","lvl": 2,"steps": ["A negative exponent means one over the positive power: 2⁻³ = {1/2³}.","Find 2³ = 2 × 2 × 2."]},{"id": "8.3-06","std": "8.3","q": "Simplify: x⁵ · x⁻²","a": "x³","lvl": 2,"also": ["x^3"],"steps": ["Same base, multiplying: add the exponents: 5 + (−2).","Keep the base x."]},{"id": "8.3-07","std": "8.3","q": "Simplify: (x⁴)³","a": "x¹²","lvl": 2,"also": ["x^12"],"steps": ["A power of a power: multiply the exponents: 4 × 3.","Keep the base x."]},{"id": "8.3-08","std": "8.3","q": "Evaluate: 3⁻² × 3⁵","a": "27","lvl": 2,"also": ["3³"],"steps": ["Same base, multiplying: add the exponents: −2 + 5.","Then find 3 to that power."]},{"id": "8.3-09","std": "8.3","q": "Simplify and write with a positive exponent: {a³/a⁷}","a": "{1/a⁴}","lvl": 3,"also": ["1/a^4","a^-4"],"steps": ["Same base, dividing: subtract the exponents: 3 − 7.","A negative exponent means one over the positive power."]},{"id": "8.3-10","std": "8.3","q": "Evaluate: (−2)⁴","a": "16","lvl": 2,"steps": ["The −2 is in parentheses, so the negative is multiplied too: (−2)(−2)(−2)(−2).","Count the negatives. An even number of negatives gives a positive."]},{"id": "8.3-11","std": "8.3","q": "Evaluate: −2⁴","a": "−16","lvl": 3,"steps": ["No parentheses: only the 2 is raised to the 4th power. The negative waits.","Find 2⁴ first, then make it negative."]},{"id": "8.3-12","std": "8.3","q": "Simplify: (3x²)³","a": "27x⁶","lvl": 3,"also": ["27x^6"],"steps": ["Raise each part inside to the 3rd power: 3³ and (x²)³.","3³ = 3 × 3 × 3. For (x²)³, multiply the exponents."]},{"id": "8.4-01","std": "8.4","q": "Evaluate: √144","a": "12","lvl": 1,"part": "a","steps": ["What number times itself is 144?","Try 12 × 12."]},{"id": "8.4-02","std": "8.4","q": "Evaluate: ∛125","a": "5","lvl": 1,"part": "a","steps": ["A cube root asks: what number times itself 3 times is 125?","Try 5 × 5 × 5."]},{"id": "8.4-03","std": "8.4","q": "Evaluate: √225","a": "15","lvl": 1,"part": "a","steps": ["What number times itself is 225?","It ends in 5, so try 15 × 15."]},{"id": "8.4-04","std": "8.4","q": "Evaluate: ∛1000","a": "10","lvl": 1,"part": "a","steps": ["What number times itself 3 times is 1000?","Try 10 × 10 × 10."]},{"id": "8.4-05","std": "8.4","q": "Solve: x² = 64","a": "x = ±8","lvl": 2,"also": ["8 and −8","±8"],"steps": ["Take the square root of both sides: x = √64 or x = −√64.","Both a positive and a negative number squared give 64. Write both with ±."]},{"id": "8.4-06","std": "8.4","q": "Solve: x³ = 27","a": "x = 3","lvl": 2,"steps": ["Take the cube root of both sides: x = ∛27.","What number times itself 3 times is 27?"]},{"id": "8.4-07","std": "8.4","q": "Solve: x² = 13","a": "x = ±√13","lvl": 2,"also": ["±√13"],"steps": ["Take the square root of both sides.","13 is not a perfect square, so leave it as a square root. Don't forget ±."]},{"id": "8.4-08","std": "8.4","q": "Solve: x³ = −216","a": "x = −6","lvl": 3,"steps": ["Take the cube root of both sides: x = ∛(−216).","A negative times itself 3 times stays negative. What number cubed is 216?"]},{"id": "8.4-09","std": "8.4","q": "A square has area 81 cm². What is its side length?","a": "9 cm","lvl": 1,"also": ["9"],"steps": ["A square's area is side × side.","What number times itself is 81? Use cm for the unit."]},{"id": "8.4-10","std": "8.4","q": "A cube has volume 343 in³. What is its edge length?","a": "7 in","lvl": 2,"also": ["7"],"steps": ["A cube's volume is edge × edge × edge.","What number times itself 3 times is 343? Use inches."]},{"id": "8.4-11","std": "8.4","q": "Why is √15 irrational?","a": "15 is not a perfect square, so its square root never ends or repeats","lvl": 2,"part": "b","also": ["not a perfect square"],"steps": ["Is 15 a perfect square? 3² = 9 and 4² = 16.","The square root of a number that isn't a perfect square never ends or repeats."]},{"id": "8.4-12","std": "8.4","q": "Solve: 2x² = 50","a": "x = ±5","lvl": 3,"also": ["±5"],"steps": ["Divide both sides by 2 first. Now it's x² = 25.","Take the square root of both sides. Don't forget ±."]},{"id": "8.5-01","std": "8.5","q": "Write 4,500,000 in scientific notation.","a": "4.5 × 10⁶","lvl": 1,"steps": ["Scientific notation is a number from 1 to 10 times a power of 10.","Move the decimal to make 4.5. Count how many places you moved it."]},{"id": "8.5-02","std": "8.5","q": "Write 0.00072 in scientific notation.","a": "7.2 × 10⁻⁴","lvl": 1,"steps": ["Move the decimal right until you get a number from 1 to 10: 7.2.","Count the places you moved. Moving right for a small number makes the exponent negative."]},{"id": "8.5-03","std": "8.5","q": "Write 3.1 × 10⁵ in standard form.","a": "310,000","lvl": 1,"steps": ["10⁵ means move the decimal 5 places to the right.","Start with 3.1 and move the decimal 5 places, adding zeros."]},{"id": "8.5-04","std": "8.5","q": "Which is greater: 6 × 10⁸ or 9 × 10⁷?","a": "6 × 10⁸","lvl": 2,"steps": ["Compare the powers of 10 first: 10⁸ and 10⁷.","The bigger power of 10 is the bigger number, no matter the front number."]},{"id": "8.5-05","std": "8.5","q": "Estimate 49,800,000 as a single digit times a power of 10.","a": "5 × 10⁷","lvl": 2,"steps": ["Round 49,800,000 to one digit: about 50,000,000.","Write 50,000,000 as 5 times a power of 10. Count the zeros."]},{"id": "8.5-06","std": "8.5","q": "The Sun is about 1.5 × 10⁸ km from Earth. The Moon is about 4 × 10⁵ km away. About how many times farther is the Sun?","a": "About 375 times","lvl": 3,"also": ["375"],"steps": ["How many times farther means divide: (1.5 × 10⁸) ÷ (4 × 10⁵).","Divide the front numbers: 1.5 ÷ 4. Subtract the exponents: 8 − 5.","Multiply them together to get a regular number."]},{"id": "8.5-07","std": "8.5","q": "Order from least to greatest: 3 × 10⁻², 5 × 10⁻³, 1 × 10⁻¹","a": "5 × 10⁻³, 3 × 10⁻², 1 × 10⁻¹","lvl": 2,"steps": ["Compare the powers of 10 first: 10⁻³ is the smallest and 10⁻¹ is the biggest.","Write them from the smallest power to the biggest."]},{"id": "8.5-08","std": "8.5","q": "A city has about 8 × 10⁶ people. A town has about 2 × 10⁴. How many times as many people live in the city?","a": "400","lvl": 2,"also": ["4 × 10²"],"steps": ["How many times as many means divide: (8 × 10⁶) ÷ (2 × 10⁴).","Divide the front numbers: 8 ÷ 2. Subtract the exponents: 6 − 4.","Multiply them together to get a regular number."]},{"id": "8.6-01","std": "8.6","q": "Find: (3 × 10⁴)(2 × 10⁵)","a": "6 × 10⁹","lvl": 1,"steps": ["Multiply the front numbers: 3 × 2.","Add the exponents: 10⁴ × 10⁵ = 10⁴⁺⁵."]},{"id": "8.6-02","std": "8.6","q": "Find: (8 × 10⁹) ÷ (2 × 10³)","a": "4 × 10⁶","lvl": 1,"steps": ["Divide the front numbers: 8 ÷ 2.","Subtract the exponents: 9 − 3."]},{"id": "8.6-03","std": "8.6","q": "Find: (5 × 10³)(4 × 10²). Write it in scientific notation.","a": "2 × 10⁶","lvl": 2,"steps": ["Multiply the front numbers: 5 × 4. Add the exponents: 3 + 2.","20 is bigger than 10. Rewrite 20 as 2 × 10¹ and add 1 more to the exponent."]},{"id": "8.6-04","std": "8.6","q": "Find: (6.3 × 10⁵) + (2.1 × 10⁵)","a": "8.4 × 10⁵","lvl": 2,"steps": ["The powers of 10 match, so add the front numbers: 6.3 + 2.1.","Keep × 10⁵."]},{"id": "8.6-05","std": "8.6","q": "Find: (4.5 × 10⁶) − (3 × 10⁵)","a": "4.2 × 10⁶","lvl": 3,"steps": ["Make the powers match first: 3 × 10⁵ = 0.3 × 10⁶.","Now subtract the front numbers: 4.5 − 0.3. Keep × 10⁶."]},{"id": "8.6-06","std": "8.6","q": "Find: 2,000 × (3.5 × 10⁴). Write it in scientific notation.","a": "7 × 10⁷","lvl": 2,"steps": ["Write 2,000 in scientific notation: 2 × 10³.","Multiply the front numbers: 2 × 3.5. Add the exponents: 3 + 4."]},{"id": "8.6-07","std": "8.6","q": "Find: (1.2 × 10⁻³) ÷ (4 × 10²)","a": "3 × 10⁻⁶","lvl": 3,"steps": ["Divide the front numbers: 1.2 ÷ 4.","Subtract the exponents: −3 − 2.","0.3 is less than 1. Rewrite it as 3 × 10⁻¹ and add the exponents."]},{"id": "8.6-08","std": "8.6","q": "A calculator shows 5.6E7. Write it in scientific notation.","a": "5.6 × 10⁷","lvl": 1,"part": "b","steps": ["On a calculator, E means × 10 to that power.","So E7 means × 10⁷."]},{"id": "8.6-09","std": "8.6","q": "A calculator shows 2.3E−4. Write it in standard form.","a": "0.00023","lvl": 2,"part": "b","steps": ["E−4 means × 10⁻⁴: move the decimal 4 places to the left.","Start with 2.3 and move the decimal 4 places left, adding zeros."]},{"id": "8.6-10","std": "8.6","q": "Which unit fits the width of a human hair best (about 8 × 10⁻⁵ m)? Kilometers, meters, or micrometers?","a": "Micrometers","lvl": 2,"part": "a","choices": ["Kilometers","Meters","Micrometers"],"steps": ["8 × 10⁻⁵ m is 0.00008 m. That's tiny.","Which unit is made for tiny lengths: kilometers, meters, or micrometers?"]},{"id": "8.6-11","std": "8.6","q": "Which unit fits the distance between two cities best? Millimeters, centimeters, or kilometers?","a": "Kilometers","lvl": 1,"part": "a","choices": ["Millimeters","Centimeters","Kilometers"],"steps": ["Cities are many miles apart.","Which unit is made for long distances?"]},{"id": "8.7-01","std": "8.7","q": "Is y = 6x proportional?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Proportional means y = kx: a number times x, with nothing added.","Does y = 6x look like that?"]},{"id": "8.7-02","std": "8.7","q": "Is y = 2x + 5 proportional?","a": "No (it does not pass through the origin)","lvl": 1,"choices": ["Yes","No (it does not pass through the origin)"],"steps": ["Proportional means y = kx with nothing added. Here 5 is added.","Put in x = 0. Does the line go through (0, 0)?"]},{"id": "8.7-03","std": "8.7","q": "x: 2, 4, 6 and y: 7, 14, 21. Proportional or non-proportional?","a": "Proportional (y ÷ x = 3.5)","lvl": 2,"also": ["proportional"],"steps": ["Divide each y by its x: 7 ÷ 2, 14 ÷ 4, 21 ÷ 6.","Proportional means you get the same number every time."]},{"id": "8.7-04","std": "8.7","q": "x: 1, 2, 3 and y: 3, 5, 7. Proportional or non-proportional?","a": "Non-proportional","lvl": 2,"also": ["not proportional","no"],"steps": ["Divide each y by its x: 3 ÷ 1, 5 ÷ 2, 7 ÷ 3.","Proportional means you get the same number every time. Do you?"]},{"id": "8.7-05","std": "8.7","q": "A taxi charges §3 plus §2 a mile. Is the cost proportional to the miles?","a": "No (the §3 start fee)","lvl": 2,"also": ["no"],"steps": ["At 0 miles, what does the ride cost?","Proportional means 0 miles costs §0. Does it?"]},{"id": "8.7-06","std": "8.7","q": "Apples cost §1.50 a pound with no other fees. Is the cost proportional to the pounds?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Cost = 1.50 × pounds, with no fee added.","At 0 pounds, the cost is §0. Does that fit y = kx?"]},{"id": "8.7-07","std": "8.7","q": "A line passes through (0, 0) and (3, 12). Is it proportional?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A proportional line goes through (0, 0). This one does.","Check the rate: 12 ÷ 3. Is it a straight line through the origin?"]},{"id": "8.7-08","std": "8.7","q": "A line passes through (0, 4) and (2, 8). Is it proportional?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["A proportional line has to go through (0, 0).","This line goes through (0, 4). Is that the origin?"]},{"id": "8.8-01","std": "8.8","q": "A proportional graph passes through (4, 10). What is the slope?","a": "2{1/2}","lvl": 1,"part": "a","also": ["2.5"],"steps": ["For a proportional graph, slope = y ÷ x.","Divide: 10 ÷ 4. Write it as a mixed number."]},{"id": "8.8-02","std": "8.8","q": "Write the equation of a proportional line through (5, 15).","a": "y = 3x","lvl": 1,"part": "a","steps": ["A proportional line is y = kx, and k = y ÷ x.","Find k: 15 ÷ 5. Then write y = kx."]},{"id": "8.8-03","std": "8.8","q": "A car travels 180 miles in 3 hours at a constant rate. What is the slope of the distance-time graph? What does it mean?","a": "60; the car goes 60 miles per hour","lvl": 2,"part": "a","also": ["60"],"steps": ["Slope = distance ÷ time: 180 ÷ 3.","Say what that number means with units: miles per hour."]},{"id": "8.8-04","std": "8.8","q": "In y = 0.75x, what is the unit rate?","a": "0.75","lvl": 1,"part": "a","steps": ["In y = kx, the unit rate is k, the number in front of x."]},{"id": "8.8-05","std": "8.8","q": "Which point must every proportional graph pass through?","a": "(0, 0)","lvl": 1,"also": ["the origin","origin"],"steps": ["At x = 0, a proportional graph has y = k × 0.","What point is that?"]},{"id": "8.8-06","std": "8.8","q": "A proportional graph of earnings shows (8, 96) for 8 hours. Write the equation.","a": "y = 12x","lvl": 2,"part": "a","steps": ["k = y ÷ x: 96 ÷ 8.","Write it as y = kx."]},{"id": "8.8-07","std": "8.8","q": "Two workers: Ana's graph is y = 14x; Ben earns §45 in 3 hours. Who earns more per hour?","a": "Ben (§15 per hour)","lvl": 3,"part": "a","also": ["Ben"],"steps": ["Ana earns §14 per hour from her equation.","Ben's rate is 45 ÷ 3. Compare the two rates."]},{"id": "8.8-08","std": "8.8","q": "A proportional line passes through (6, 4). Find y when x = 9.","a": "6","lvl": 2,"steps": ["Find k: 4 ÷ 6, which simplifies to {2/3}.","Use y = kx with x = 9: y = {2/3} × 9."]},{"id": "8.9-01","std": "8.9","q": "Find the slope of the line through (1, 2) and (3, 8).","a": "3","lvl": 1,"part": "b","steps": ["Slope = change in y ÷ change in x: {8 − 2/3 − 1}.","Subtract the tops and the bottoms, then divide."]},{"id": "8.9-02","std": "8.9","q": "Find the slope of the line through (−2, 5) and (2, −3).","a": "−2","lvl": 2,"part": "b","steps": ["Slope = change in y ÷ change in x: {−3 − 5/2 − (−2)}.","Top: −3 − 5. Bottom: 2 + 2. Then divide."]},{"id": "8.9-03","std": "8.9","q": "Find the slope of the line through (0, 4) and (6, 7).","a": "{1/2}","lvl": 2,"part": "b","steps": ["Slope = change in y ÷ change in x: {7 − 4/6 − 0}.","Find the top and bottom, then simplify the fraction."]},{"id": "8.9-04","std": "8.9","q": "What are the slope and y-intercept of y = −2x + 7?","a": "Slope −2, y-intercept 7","lvl": 1,"part": "c","also": ["m = −2, b = 7"],"steps": ["In y = mx + b, m is the slope and b is the y-intercept.","Match: m is the number in front of x, and b is the number added."]},{"id": "8.9-05","std": "8.9","q": "A plumber charges §50 to come out plus §40 an hour. Write the cost as y = mx + b.","a": "y = 40x + 50","lvl": 2,"part": "c","steps": ["y = mx + b: m is the cost per hour, and b is the starting fee.","Put in m = 40 and b = 50."]},{"id": "8.9-06","std": "8.9","q": "In y = 40x + 50 (plumber cost), what does 50 mean?","a": "The §50 starting fee (the initial value)","lvl": 2,"part": "c","also": ["50","starting fee"],"steps": ["In y = mx + b, b is what you pay when x = 0.","What do you pay before any hours of work?"]},{"id": "8.9-07","std": "8.9","q": "Write the equation of the line with slope 4 and y-intercept −3.","a": "y = 4x − 3","lvl": 1,"part": "c","steps": ["Use y = mx + b.","Put in m = 4 and b = −3."]},{"id": "8.9-08","std": "8.9","q": "Two slope triangles on the same line have {rise/run} = {2/3} and {6/9}. Why are the slopes the same?","a": "The triangles are similar, so {6/9} = {2/3}","lvl": 3,"part": "a","also": ["similar triangles"],"steps": ["Simplify {6/9}. What do you get?","The two triangles are the same shape, just different sizes. Same shape on the same line means the same slope."]},{"id": "8.9-09","std": "8.9","q": "Lines y = 3x + 1 and y = 3x − 4 have the same slope. Are they the same line?","a": "No; they are parallel with different y-intercepts","lvl": 2,"part": "d","also": ["no"],"steps": ["Both have slope 3, so they point the same way.","Check the y-intercepts: 1 and −4. Do they cross the y-axis at the same point?"]},{"id": "8.9-10","std": "8.9","q": "Line A goes through (0, 2) and (1, 5). Line B goes through (0, −1) and (2, 5). Do they have the same slope? Do they have the same y-intercept?","a": "Same slope (3), different y-intercepts (2 and −1)","lvl": 3,"part": "d","steps": ["Line A: slope = {5 − 2/1 − 0}. Line B: slope = {5 − (−1)/2 − 0}.","The y-intercept is the y-value at x = 0 for each line.","Compare the slopes, then compare the y-intercepts."]},{"id": "8.9-11","std": "8.9","q": "What is the slope of a horizontal line?","a": "0","lvl": 1,"part": "b","steps": ["A horizontal line is flat: y never changes.","Slope = change in y ÷ change in x. What is the change in y?"]},{"id": "8.10-01","std": "8.10","q": "Plan A: y = 8x. Plan B costs §20 plus §5 per month. Which costs less for 4 months?","a": "Plan A (§32 vs §40)","lvl": 2,"also": ["Plan A","A"],"steps": ["Plan A for 4 months: 8 × 4.","Plan B for 4 months: 20 + 5 × 4.","Compare the two costs."]},{"id": "8.10-02","std": "8.10","q": "Plan A: y = 8x. Plan B: y = 5x + 20. After how many months do they cost the same?","a": "x = 6{2/3} months (about 6.7)","lvl": 3,"also": ["6{2/3}","6{2/3}"],"steps": ["Set the plans equal: 8x = 5x + 20.","Subtract 5x on both sides. Now it's 3x = 20.","Divide both sides by 3. Write it as a mixed number."]},{"id": "8.10-03","std": "8.10","q": "Car A: y = 55x (miles in x hours). Car B travels 240 miles in 4 hours. Which car is faster?","a": "Car B (60 mph)","lvl": 2,"also": ["B","Car B"],"steps": ["Car A goes 55 miles per hour.","Car B's rate: 240 ÷ 4. Compare the speeds."]},{"id": "8.10-04","std": "8.10","q": "Gym A: §30 a month. Gym B: §60 to join plus §20 a month. Which relationship is proportional?","a": "Gym A","lvl": 1,"also": ["A"],"steps": ["Proportional means the cost is §0 for 0 months.","Does either gym charge a fee to join?"]},{"id": "8.10-05","std": "8.10","q": "Gym A: §30 a month. Gym B: §60 to join plus §20 a month. Which costs less for 12 months?","a": "Gym B (§300 vs §360)","lvl": 3,"also": ["B","Gym B"],"steps": ["Gym A for 12 months: 30 × 12.","Gym B for 12 months: 60 + 20 × 12.","Compare the two costs."]},{"id": "8.10-06","std": "8.10","q": "A table shows x: 1, 2, 3 and y: 9, 18, 27. Another relationship is y = 9x + 1. Which is proportional?","a": "The table","lvl": 2,"steps": ["Check the table: divide each y by its x: 9 ÷ 1, 18 ÷ 2, 27 ÷ 3.","Does y = 9x + 1 go through (0, 0)? Put in x = 0."]},{"id": "8.10-07","std": "8.10","q": "Which has the greater rate of change: y = 2.5x + 4 or a line through (0, 0) and (2, 6)?","a": "The line through (0, 0) and (2, 6) (rate 3)","lvl": 2,"also": ["the line","3"],"steps": ["The rate of change of y = 2.5x + 4 is 2.5.","The other line's rate: 6 ÷ 2. Which rate is bigger?"]},{"id": "8.10-08","std": "8.10","q": "Phone plan A: §0.10 per text. Plan B: §5 a month plus §0.05 per text. Which costs less for 200 texts?","a": "Plan B (§15 vs §20)","lvl": 3,"also": ["Plan B","B"],"steps": ["Plan A for 200 texts: 0.10 × 200.","Plan B for 200 texts: 5 + 0.05 × 200.","Compare the two costs."]},{"id": "8.11-01","std": "8.11","q": "Solve: 5x − 3 = 2x + 12","a": "x = 5","lvl": 1,"steps": ["Get the x's on one side: subtract 2x on both sides. Now it's 3x − 3 = 12.","Undo the 3: add 3 on both sides. Now it's 3x = 15.","Divide both sides by 3."]},{"id": "8.11-02","std": "8.11","q": "Solve: 7x + 4 = 3x − 8","a": "x = −3","lvl": 2,"steps": ["Get the x's on one side: subtract 3x on both sides. Now it's 4x + 4 = −8.","Undo the 4: subtract 4 on both sides. Now it's 4x = −12.","Divide both sides by 4."]},{"id": "8.11-03","std": "8.11","q": "Solve: −2x + 9 = 4x − 15","a": "x = 4","lvl": 2,"steps": ["Keep the x's on the side with more: add 2x on both sides. Now it's 9 = 6x − 15.","Undo the 15: add 15 on both sides. Now it's 24 = 6x.","Divide both sides by 6."]},{"id": "8.11-04","std": "8.11","q": "Solve: 3(x + 4) = 27","a": "x = 5","lvl": 1,"steps": ["Divide both sides by 3 first. Now it's x + 4 = 9.","Undo the 4: subtract 4 on both sides."]},{"id": "8.11-05","std": "8.11","q": "Solve: 4(2x − 1) = 3x + 11","a": "x = 3","lvl": 2,"steps": ["Distribute the 4: 8x − 4 = 3x + 11.","Subtract 3x on both sides. Now it's 5x − 4 = 11.","Add 4 on both sides, then divide by 5."]},{"id": "8.11-06","std": "8.11","q": "Solve: 2(x + 5) = 3(x − 1)","a": "x = 13","lvl": 2,"steps": ["Distribute both sides: 2x + 10 = 3x − 3.","Keep the x's on the side with more: subtract 2x on both sides. Now it's 10 = x − 3.","Undo the 3: add 3 on both sides."]},{"id": "8.11-07","std": "8.11","q": "Solve: {2/3}x + 4 = 10","a": "x = 9","lvl": 2,"steps": ["Undo the 4: subtract 4 on both sides. Now it's {2/3}x = 6.","Multiply both sides by {3/2}, the flip of {2/3}."]},{"id": "8.11-08","std": "8.11","q": "Solve: 0.5(x + 6) = 2x − 6","a": "x = 6","lvl": 3,"steps": ["Distribute the 0.5: 0.5x + 3 = 2x − 6.","Subtract 0.5x on both sides. Now it's 3 = 1.5x − 6.","Add 6 on both sides, then divide by 1.5."]},{"id": "8.11-09","std": "8.11","q": "Solve: 7x − 3x + 5 = 21","a": "x = 4","lvl": 1,"steps": ["Combine like terms first: 7x − 3x. Now it's 4x + 5 = 21.","Undo the 5: subtract 5 on both sides, then divide by 4."]},{"id": "8.11-10","std": "8.11","q": "Solve: 4x + 7 = 4x − 2","a": "No solution","lvl": 2,"part": "a","choices": ["One solution","No solution","Infinitely many solutions"],"steps": ["Subtract 4x on both sides. What's left: 7 = −2.","Is 7 = −2 ever true? A statement that's never true means no number works."]},{"id": "8.11-11","std": "8.11","q": "Solve: 2(3x − 1) = 6x − 2","a": "Infinitely many solutions","lvl": 2,"part": "a","choices": ["One solution","No solution","Infinitely many solutions"],"steps": ["Distribute the 2: 6x − 2 = 6x − 2.","Both sides are exactly the same. Is that true for every x?"]},{"id": "8.11-12","std": "8.11","q": "How many solutions does 5x + 2 = 3x + 2 have?","a": "One solution (x = 0)","lvl": 2,"part": "a","choices": ["One solution (x = 0)","No solution","Infinitely many solutions"],"steps": ["Subtract 3x on both sides. Now it's 2x + 2 = 2.","The x's didn't cancel, so there's one answer. Subtract 2, then divide by 2 to find it."]},{"id": "8.11-13","std": "8.11","q": "Gym A: §20 to join plus §15 a month. Gym B: §50 to join plus §10 a month. After how many months is the cost the same?","a": "6 months","lvl": 2,"part": "b","also": ["6"],"steps": ["Write each cost: Gym A is 20 + 15m. Gym B is 50 + 10m.","Set them equal: 20 + 15m = 50 + 10m.","Subtract 10m on both sides, then subtract 20. Now it's 5m = 30. Divide by 5."]},{"id": "8.11-14","std": "8.11","q": "A rectangle's length is 5 more than its width. Its perimeter is 46. Find the length.","a": "14","lvl": 2,"part": "b","steps": ["Let w be the width. The length is w + 5.","Perimeter: 2w + 2(w + 5) = 46. Distribute and combine: 4w + 10 = 46.","Solve for w. The question wants the length, w + 5."]},{"id": "8.11-15","std": "8.11","q": "The sides of a triangle are x, x + 3 and 2x − 1. The perimeter is 30. Find the longest side.","a": "13","lvl": 3,"part": "b","steps": ["Add the sides and set them equal to 30: x + (x + 3) + (2x − 1) = 30.","Combine like terms: 4x + 2 = 30. Solve for x.","Plug x into each side. The question wants the longest one."]},{"id": "8.11-16","std": "8.11","q": "Solve: {x/2} + 3 = {x/5} + 9","a": "x = 20","lvl": 3,"steps": ["Get rid of the fractions: multiply every term by 10, the common denominator.","Now it's 5x + 30 = 2x + 90.","Subtract 2x on both sides, then subtract 30, then divide by 3."]},{"id": "8.12-01","std": "8.12","q": "Solve by substitution: y = 2x and x + y = 12","a": "(4, 8)","lvl": 1,"steps": ["Put 2x in for y in the second equation: x + 2x = 12.","Combine like terms and solve for x.","Put x back into y = 2x to get y. Write it as (x, y)."]},{"id": "8.12-02","std": "8.12","q": "Solve by substitution: y = x + 3 and 2x + y = 18","a": "(5, 8)","lvl": 2,"steps": ["Put x + 3 in for y: 2x + (x + 3) = 18.","Combine like terms: 3x + 3 = 18. Solve for x.","Put x back into y = x + 3. Write it as (x, y)."]},{"id": "8.12-03","std": "8.12","q": "Solve: y = 3x − 5 and y = x + 7","a": "(6, 13)","lvl": 2,"steps": ["Both equal y, so set them equal: 3x − 5 = x + 7.","Subtract x on both sides, then add 5. Now it's 2x = 12. Solve for x.","Put x back into y = x + 7. Write it as (x, y)."]},{"id": "8.12-04","std": "8.12","q": "Solve: y = −x + 4 and y = 2x − 2","a": "(2, 2)","lvl": 2,"steps": ["Both equal y, so set them equal: −x + 4 = 2x − 2.","Add x on both sides, then add 2. Now it's 6 = 3x. Solve for x.","Put x back into y = 2x − 2. Write it as (x, y)."]},{"id": "8.12-05","std": "8.12","q": "Two lines cross at (3, −1). What is the solution to the system?","a": "(3, −1)","lvl": 1,"part": "a","steps": ["The solution to a system is the point where the lines cross.","Write that point as (x, y)."]},{"id": "8.12-06","std": "8.12","q": "Why is the point where two lines cross the solution to the system?","a": "It is on both lines, so it makes both equations true","lvl": 2,"part": "a","steps": ["Every point on a line makes that line's equation true.","The crossing point is on both lines. What does that mean for both equations?"]},{"id": "8.12-07","std": "8.12","q": "How many solutions does y = 2x + 1 and y = 2x − 3 have?","a": "No solution (parallel lines)","lvl": 2,"part": "b","choices": ["One solution","No solution (parallel lines)","Infinitely many solutions"],"steps": ["Both lines have slope 2, but the y-intercepts are 1 and −3.","Same slope with different y-intercepts means parallel lines. Do parallel lines ever cross?"]},{"id": "8.12-08","std": "8.12","q": "How many solutions does y = 3x + 2 and 2y = 6x + 4 have?","a": "Infinitely many solutions (same line)","lvl": 3,"part": "b","choices": ["One solution","No solution","Infinitely many solutions (same line)"],"steps": ["Divide the second equation by 2: y = 3x + 2.","Compare it with the first equation. Same line means every point works."]},{"id": "8.12-09","std": "8.12","q": "Adult tickets are §8 and child tickets are §5. 20 tickets cost §130. How many adult tickets were sold?","a": "10","lvl": 3,"part": "b","steps": ["Let a be adult tickets and c be child tickets: a + c = 20 and 8a + 5c = 130.","From the first: c = 20 − a. Put it in: 8a + 5(20 − a) = 130.","Distribute and combine: 3a + 100 = 130. Solve for a."]},{"id": "8.12-10","std": "8.12","q": "Is (2, 5) a solution to y = 2x + 1 and y = x + 3?","a": "Yes (5 = 5 in both)","lvl": 2,"part": "a","also": ["yes"],"steps": ["Put x = 2 and y = 5 into y = 2x + 1. Is 5 = 2(2) + 1?","Now check y = x + 3. Is 5 = 2 + 3?","It's a solution only if both are true."]},{"id": "8.12-11","std": "8.12","q": "Store A: §10 plus §4 a shirt. Store B: §6 a shirt. When do they cost the same? How many shirts and what cost?","a": "5 shirts, §30","lvl": 3,"part": "b","also": ["(5, 30)"],"steps": ["Store A: 10 + 4s. Store B: 6s. Set them equal: 10 + 4s = 6s.","Subtract 4s on both sides. Now it's 10 = 2s. Solve for s.","Find the cost: put s into 6s."]},{"id": "8.13-01","std": "8.13","q": "Is {(1, 2), (2, 4), (3, 6)} a function?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A function gives each input exactly one output.","Look at the x-values: 1, 2, 3. Does any x show up twice?"]},{"id": "8.13-02","std": "8.13","q": "Is {(1, 2), (1, 5), (3, 6)} a function?","a": "No (input 1 has two outputs)","lvl": 1,"choices": ["Yes","No (input 1 has two outputs)"],"steps": ["A function gives each input exactly one output.","Look at the x-values. Input 1 shows up twice. Does it have the same output both times?"]},{"id": "8.13-03","std": "8.13","q": "Is {(4, 1), (5, 1), (6, 1)} a function?","a": "Yes (each input has one output)","lvl": 2,"choices": ["Yes (each input has one output)","No"],"steps": ["A function gives each input exactly one output.","The inputs are 4, 5 and 6. Different inputs can share an output. Does any input have two outputs?"]},{"id": "8.13-04","std": "8.13","q": "Does a vertical line pass the vertical line test?","a": "No","lvl": 2,"choices": ["Yes","No"],"steps": ["The test: if any vertical line hits the graph more than once, it's not a function.","A vertical line laid on top of a vertical line touches it at how many points?"]},{"id": "8.13-05","std": "8.13","q": "A table has x: 1, 2, 2, 3 and y: 4, 5, 6, 7. Is it a function?","a": "No (x = 2 has two outputs)","lvl": 1,"also": ["no"],"steps": ["A function gives each input exactly one output.","x = 2 shows up twice. What are its outputs?"]},{"id": "8.13-06","std": "8.13","q": "In a function, each input has exactly ___ output.","a": "One","lvl": 1,"also": ["1"],"steps": ["Think about a vending machine: each button gives you how many snacks?","In a function, each input gets just ___ output."]},{"id": "8.13-07","std": "8.13","q": "A mapping sends 1 → 3, 2 → 3, 3 → 5. Is it a function?","a": "Yes","lvl": 2,"choices": ["Yes","No"],"steps": ["A function gives each input exactly one output.","1 and 2 both go to 3. That's fine. Does any input go to two outputs?"]},{"id": "8.13-08","std": "8.13","q": "Is x = y² (for example (4, 2) and (4, −2)) a function of x?","a": "No","lvl": 3,"choices": ["Yes","No"],"steps": ["Look at the examples: x = 4 gives y = 2 and y = −2.","One input with two outputs. Can that be a function?"]},{"id": "8.14-01","std": "8.14","q": "f(x) = 3x − 4. Find f(5).","a": "11","lvl": 1,"steps": ["Put 5 in for x: f(5) = 3(5) − 4.","Multiply first, then subtract."]},{"id": "8.14-02","std": "8.14","q": "f(x) = −2x + 7. Find f(−3).","a": "13","lvl": 1,"steps": ["Put −3 in for x: f(−3) = −2(−3) + 7.","Negative × negative is positive. Then add 7."]},{"id": "8.14-03","std": "8.14","q": "g(x) = x² + 1. Find g(4).","a": "17","lvl": 2,"steps": ["Put 4 in for x: g(4) = 4² + 1.","Square first, then add 1."]},{"id": "8.14-04","std": "8.14","q": "h(x) = {1/2}x + 6. Find h(10).","a": "11","lvl": 1,"steps": ["Put 10 in for x: h(10) = {1/2}(10) + 6.","Half of 10 first, then add 6."]},{"id": "8.14-05","std": "8.14","q": "f(x) = 5x + 2. Find x when f(x) = 27.","a": "x = 5","lvl": 3,"steps": ["Set the function equal to 27: 5x + 2 = 27.","Subtract 2 on both sides, then divide by 5."]},{"id": "8.14-06","std": "8.14","q": "y = 4x − 1. Find y when x = −2.","a": "−9","lvl": 1,"steps": ["Put −2 in for x: y = 4(−2) − 1.","Multiply first, then subtract 1."]},{"id": "8.14-07","std": "8.14","q": "C(t) = 12t + 15 is the cost of t tickets. Find C(6).","a": "87","lvl": 2,"also": ["§87"],"steps": ["Put 6 in for t: C(6) = 12(6) + 15.","Multiply first, then add 15."]},{"id": "8.14-08","std": "8.14","q": "f(x) = x² − 3x. Find f(−2).","a": "10","lvl": 3,"steps": ["Put −2 in for x: f(−2) = (−2)² − 3(−2).","(−2)² = 4 and −3(−2) = 6.","Combine them: 4 − (−6) means 4 + 6."]},{"id": "8.15-01","std": "8.15","q": "Is y = x² linear or non-linear?","a": "Non-linear","lvl": 1,"part": "a","choices": ["Linear","Non-linear"],"steps": ["A linear function has x to the first power only, like y = mx + b.","Here x is squared. Does it make a straight line?"]},{"id": "8.15-02","std": "8.15","q": "Is y = 4 − 3x linear or non-linear?","a": "Linear","lvl": 1,"part": "a","choices": ["Linear","Non-linear"],"steps": ["Rewrite it: y = −3x + 4.","Does it look like y = mx + b?"]},{"id": "8.15-03","std": "8.15","q": "Table: x 0, 1, 2, 3 and y 1, 2, 4, 8. Linear or non-linear?","a": "Non-linear (y doubles)","lvl": 2,"part": "a","also": ["non-linear","nonlinear"],"steps": ["Find how y changes each time x goes up 1: 1 to 2, 2 to 4, 4 to 8.","Linear means y changes by the same amount every time. Does it?"]},{"id": "8.15-04","std": "8.15","q": "Table: x 0, 1, 2, 3 and y 5, 8, 11, 14. Linear or non-linear?","a": "Linear (adds 3 each time)","lvl": 2,"part": "a","also": ["linear"],"steps": ["Find how y changes each time x goes up 1: 5 to 8, 8 to 11, 11 to 14.","Linear means y changes by the same amount every time. Does it?"]},{"id": "8.15-05","std": "8.15","q": "Function A: y = 3x + 2. Function B goes through (0, 5) and (2, 9). Which has the greater rate of change?","a": "Function A (3 vs 2)","lvl": 2,"also": ["A"],"steps": ["Function A's rate is 3, the number in front of x.","Function B's rate: {9 − 5/2 − 0}. Which rate is bigger?"]},{"id": "8.15-06","std": "8.15","q": "Function A: y = 3x + 2. Function B goes through (0, 5) and (2, 9). Which has the greater y-intercept?","a": "Function B (5 vs 2)","lvl": 2,"also": ["B"],"steps": ["Function A's y-intercept is 2, the number added.","Function B's y-intercept is its y-value when x = 0. Which is bigger?"]},{"id": "8.15-07","std": "8.15","q": "Is y = {6/x} linear?","a": "No","lvl": 2,"part": "a","choices": ["Yes","No"],"steps": ["Here x is on the bottom of the fraction.","Try x = 1, 2, 3: y = 6, 3, 2. Does y change by the same amount each time?"]},{"id": "8.15-08","std": "8.15","q": "Ana saves §10 a week starting with §25. Ben's savings are y = 12x. Who saves faster each week?","a": "Ben (§12 vs §10)","lvl": 2,"also": ["Ben"],"steps": ["Ana saves §10 a week. The §25 is just her start.","Ben's rate is the number in front of x. Compare the two rates."]},{"id": "8.16-01","std": "8.16","q": "A pool has 500 gallons and drains 20 gallons a minute. Write a function for the gallons left.","a": "y = 500 − 20x","lvl": 1,"also": ["y = −20x + 500"],"steps": ["Start: 500 gallons. Rate: −20 gallons each minute.","Write it as y = start + rate × x."]},{"id": "8.16-02","std": "8.16","q": "Write the function for the line through (0, 3) and (2, 11).","a": "y = 4x + 3","lvl": 2,"steps": ["The y-intercept is 3, from the point (0, 3).","Slope = {11 − 3/2 − 0}. Then write y = mx + b."]},{"id": "8.16-03","std": "8.16","q": "Write the function for the line through (1, 5) and (3, 9).","a": "y = 2x + 3","lvl": 2,"steps": ["Slope = {9 − 5/3 − 1}.","Put the slope and (1, 5) into y = mx + b to find b: 5 = m(1) + b.","Write y = mx + b."]},{"id": "8.16-04","std": "8.16","q": "A table shows x: 0, 1, 2 and y: 7, 4, 1. Write the function.","a": "y = −3x + 7","lvl": 2,"steps": ["The y-intercept is the y-value at x = 0.","Find how y changes each time x goes up 1: 7 to 4 to 1. That's the slope.","Write y = mx + b."]},{"id": "8.16-05","std": "8.16","q": "A phone costs §40 a month plus §100 for the phone. What are the rate of change and initial value?","a": "Rate §40 per month, initial value §100","lvl": 1,"part": "a","also": ["40 and 100"],"steps": ["The rate of change is what you pay each month.","The initial value is what you pay at the start, before any months."]},{"id": "8.16-06","std": "8.16","q": "A candle is 12 in tall and burns 1.5 in per hour. Write a function for its height h after t hours.","a": "h = 12 − 1.5t","lvl": 2,"part": "a","also": ["h = −1.5t + 12"],"steps": ["Start: 12 inches. Rate: −1.5 inches each hour.","Write it as h = start + rate × t."]},{"id": "8.16-07","std": "8.16","q": "A line goes through (2, 10) and (5, 19). What is the rate of change?","a": "3","lvl": 2,"part": "a","steps": ["Rate of change = change in y ÷ change in x: {19 − 10/5 − 2}.","Subtract the tops and the bottoms, then divide."]},{"id": "8.16-08","std": "8.16","q": "In y = −1.5t + 12 (candle height), what does −1.5 mean?","a": "The candle gets 1.5 inches shorter each hour","lvl": 2,"part": "a","steps": ["−1.5 is the rate of change: inches for each hour.","Negative means the height goes down. Say it in words."]},{"id": "8.16-09","std": "8.16","q": "Write the function for the line through (−2, 1) and (2, 9).","a": "y = 2x + 5","lvl": 3,"steps": ["Slope = {9 − 1/2 − (−2)}. Top: 8. Bottom: 4.","Put the slope and (2, 9) into y = mx + b to find b.","Write y = mx + b."]},{"id": "8.17-01","std": "8.17","q": "A graph of a car's distance from home goes up in a straight line. Is the distance increasing or decreasing? Linear or non-linear?","a": "Increasing, linear","lvl": 1,"also": ["increasing linear"],"steps": ["Going up from left to right means the value is getting bigger.","A straight line means a constant rate. Is that linear?"]},{"id": "8.17-02","std": "8.17","q": "A graph of a ball's height goes up, then curves back down. Is it linear or non-linear?","a": "Non-linear","lvl": 1,"choices": ["Linear","Non-linear"],"steps": ["A straight line is linear. A curve is not.","Does the ball's graph bend?"]},{"id": "8.17-03","std": "8.17","q": "A line on a graph of water in a tank slants down from left to right. Is the water increasing or decreasing?","a": "Decreasing","lvl": 1,"choices": ["Increasing","Decreasing"],"steps": ["Read the graph from left to right.","Slanting down means the amount is getting smaller."]},{"id": "8.17-04","std": "8.17","q": "A graph of distance is flat (horizontal) from minute 5 to minute 8. What is happening?","a": "The person stopped (the distance did not change)","lvl": 2,"also": ["stopped","not moving"],"steps": ["A flat line means y doesn't change.","If the distance doesn't change for 3 minutes, what is the person doing?"]},{"id": "8.17-05","std": "8.17","q": "A graph of a phone's battery drops quickly, then more slowly. Linear or non-linear?","a": "Non-linear","lvl": 2,"choices": ["Linear","Non-linear"],"steps": ["A linear graph changes at the same rate the whole time.","Fast, then slow: is that the same rate?"]},{"id": "8.17-06","std": "8.17","q": "Sketch description: Sam walks to school at a steady pace, waits for a friend, then runs. Which part of the graph is steepest?","a": "The running part","lvl": 3,"also": ["running"],"steps": ["Steeper means faster.","Which part is fastest: walking, waiting, or running?"]},{"id": "8.17-07","std": "8.17","q": "A graph of height of a plant over weeks rises faster and faster. Is it increasing at a constant rate?","a": "No; it is non-linear","lvl": 2,"also": ["no"],"steps": ["Constant rate means the same amount each week, a straight line.","Faster and faster means the amount grows each week. Is that a straight line?"]},{"id": "8.17-08","std": "8.17","q": "On a graph, a line goes down 3 units for every 1 unit right. Is the relationship increasing or decreasing?","a": "Decreasing","lvl": 1,"choices": ["Increasing","Decreasing"],"steps": ["Going down as you move right means y gets smaller.","Smaller y as x grows: increasing or decreasing?"]},{"id": "8.18-01","std": "8.18","q": "As hours studied go up, test scores go up. What kind of association is this?","a": "Positive","lvl": 1,"choices": ["Positive","Negative","No association"],"steps": ["Both go up together.","When both go up, the association is positive."]},{"id": "8.18-02","std": "8.18","q": "As a car's age goes up, its value goes down. What kind of association?","a": "Negative","lvl": 1,"choices": ["Positive","Negative","No association"],"steps": ["One goes up while the other goes down.","Opposite directions means a negative association."]},{"id": "8.18-03","std": "8.18","q": "Shoe size and favorite color. What kind of association?","a": "No association","lvl": 1,"choices": ["Positive","Negative","No association"],"steps": ["Does shoe size change what color someone likes?","If one doesn't affect the other, there's no association."]},{"id": "8.18-04","std": "8.18","q": "Points: (1, 2), (2, 4), (3, 5), (4, 8), (5, 9), (6, 30). Which point is an outlier?","a": "(6, 30)","lvl": 2,"steps": ["Look at the pattern: y goes up by about 2 each time.","Which point is far away from that pattern?"]},{"id": "8.18-05","std": "8.18","q": "On a scatter plot, most points form a group between x = 3 and x = 5. What is that called?","a": "A cluster","lvl": 1,"also": ["cluster","clustering"],"steps": ["When many points bunch together in one spot, that group has a name.","It starts with c, like a bunch of grapes."]},{"id": "8.18-06","std": "8.18","q": "Points: (1, 9), (2, 7), (3, 6), (4, 4), (5, 2). Positive, negative, or no association?","a": "Negative","lvl": 2,"choices": ["Positive","Negative","No association"],"steps": ["Read the y-values as x goes up: 9, 7, 6, 4, 2.","y goes down as x goes up. What kind of association is that?"]},{"id": "8.18-07","std": "8.18","q": "Points curve up like a U shape. Is the association linear or non-linear?","a": "Non-linear","lvl": 2,"choices": ["Linear","Non-linear"],"steps": ["Linear means the points follow a straight line.","A U shape bends. Is it straight?"]},{"id": "8.18-08","std": "8.18","q": "Temperature outside and hot chocolate sales. Likely positive or negative association?","a": "Negative","lvl": 2,"choices": ["Positive","Negative"],"steps": ["When it's warm outside, do people buy more or less hot chocolate?","One goes up while the other goes down. What kind of association?"]},{"id": "8.19-01","std": "8.19","q": "A good line of fit should have about how many points above and below it?","a": "About the same number above and below","lvl": 1,"also": ["the same","equal"],"steps": ["A line of fit goes through the middle of the data.","Picture the points on both sides of it. How many should be above, and how many below?"]},{"id": "8.19-02","std": "8.19","q": "Points cluster close to a line of fit. Is it a good fit?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A good fit means the points stay close to the line.","These points are close. Is it a good fit?"]},{"id": "8.19-03","std": "8.19","q": "A line of fit passes through (0, 10) and (5, 35). What is its equation?","a": "y = 5x + 10","lvl": 2,"steps": ["The y-intercept is 10, from the point (0, 10).","Slope = {35 − 10/5 − 0}. Then write y = mx + b."]},{"id": "8.19-04","std": "8.19","q": "Points are spread far from the line in every direction. Is the line a good model?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["A good line of fit has points close to it.","These points are far from the line. Does it model the data well?"]},{"id": "8.19-05","std": "8.19","q": "Which line fits (1, 3), (2, 5), (3, 7), (4, 9) best? A. y = x + 2  B. y = 2x + 1  C. y = 3x","a": "B","lvl": 2,"choices": ["A","B","C"],"steps": ["Test each line with a point, like (1, 3): put x = 1 in and see if you get 3.","Then check (2, 5). The best line works for all the points."]},{"id": "8.19-06","std": "8.19","q": "Should a line of fit always go through the first and last points?","a": "No","lvl": 2,"choices": ["Yes","No"],"steps": ["A line of fit follows the whole pattern, not just two points.","What if the first or last point is an outlier?"]},{"id": "8.19-07","std": "8.19","q": "A line of fit is y = 2x + 4. A data point is (3, 13). How far above the line is it?","a": "3 units","lvl": 3,"also": ["3"],"steps": ["Find the line's y at x = 3: y = 2(3) + 4.","Compare it with the point's y, 13. Subtract to find how far above."]},{"id": "8.19-08","std": "8.19","q": "A line of fit passes through (2, 50) and (6, 70). What is its slope?","a": "5","lvl": 2,"steps": ["Slope = change in y ÷ change in x: {70 − 50/6 − 2}.","Subtract the tops and the bottoms, then divide."]},{"id": "8.20-01","std": "8.20","q": "A model is y = 3x + 20, where y is plant height in cm after x weeks. Predict the height after 10 weeks.","a": "50 cm","lvl": 1,"also": ["50"],"steps": ["Put x = 10 into the model: y = 3(10) + 20.","Multiply, then add."]},{"id": "8.20-02","std": "8.20","q": "In y = 3x + 20 (plant height), what does 3 mean?","a": "The plant grows 3 cm each week","lvl": 1,"part": "a","also": ["3 cm per week"],"steps": ["3 is the slope: how much y changes each time x goes up 1.","Say it with the units: centimeters each week."]},{"id": "8.20-03","std": "8.20","q": "In y = 3x + 20 (plant height), what does 20 mean?","a": "The plant was 20 cm tall at week 0","lvl": 1,"part": "a","also": ["starting height"],"steps": ["20 is the y-intercept: the value of y when x = 0.","x = 0 is week 0. Say what that means for the plant."]},{"id": "8.20-04","std": "8.20","q": "A model for ticket sales is y = 150x + 400 after x days. Predict sales on day 6.","a": "1,300","lvl": 2,"also": ["1300"],"steps": ["Put x = 6 into the model: y = 150(6) + 400.","Multiply, then add."]},{"id": "8.20-05","std": "8.20","q": "A model is y = −2.5x + 90, where y is test score and x is hours of TV a day. Predict the score for 4 hours.","a": "80","lvl": 2,"steps": ["Put x = 4 into the model: y = −2.5(4) + 90.","Multiply, then add."]},{"id": "8.20-06","std": "8.20","q": "Using y = −2.5x + 90 (score vs TV hours), what does −2.5 mean?","a": "The score drops 2.5 points for each extra hour of TV","lvl": 2,"part": "a","steps": ["−2.5 is the slope: the change in score for each extra hour of TV.","Negative means the score goes down. Say it in words."]},{"id": "8.20-07","std": "8.20","q": "Using y = 3x + 20 (plant height), when will the plant be 65 cm?","a": "Week 15","lvl": 3,"also": ["15"],"steps": ["Set the model equal to 65: 3x + 20 = 65.","Subtract 20 on both sides, then divide by 3."]},{"id": "8.20-08","std": "8.20","q": "A model is y = 12x + 30 for savings after x weeks. How much is saved after 8 weeks?","a": "§126","lvl": 1,"also": ["126"],"steps": ["Put x = 8 into the model: y = 12(8) + 30.","Multiply, then add."]},{"id": "8.21-01","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. How many students play sports?","a": "33","lvl": 1,"steps": ["Students who play sports: boys who play plus girls who play.","Add: 18 + 15."]},{"id": "8.21-02","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. How many girls are there?","a": "25","lvl": 1,"steps": ["Girls are the ones who play plus the ones who don't.","Add: 15 + 10."]},{"id": "8.21-03","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. What fraction of the boys play sports?","a": "{18/25}","lvl": 2,"also": ["0.72","72%"],"steps": ["Find the number of boys: 18 + 7.","Fraction of boys who play = boys who play ÷ all boys."]},{"id": "8.21-04","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. What percent of the girls play sports?","a": "60%","lvl": 2,"also": ["60"],"steps": ["Find the number of girls: 15 + 10.","Girls who play ÷ all girls, then change it to a percent."]},{"id": "8.21-05","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. Is there an association between being a boy and playing sports?","a": "Yes, a weak one (72% of boys vs 60% of girls)","lvl": 3,"also": ["yes"],"steps": ["Boys who play: 18 out of 25. Change it to a percent.","Girls who play: 15 out of 25. Change it to a percent.","If the percents are different, there's an association. Is the gap big or small?"]},{"id": "8.21-06","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. What percent of all students do not play sports?","a": "34%","lvl": 2,"also": ["34"],"steps": ["Students who don't play: 7 + 10.","Divide by all 50 students, then change it to a percent."]},{"id": "8.21-07","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. Of the students who play sports, what fraction are girls?","a": "{5/11}","lvl": 3,"steps": ["Students who play sports: 18 + 15.","Girls who play ÷ all who play. Simplify the fraction."]},{"id": "8.21-08","std": "8.21","q": "In a two-way table, a row relative frequency compares a cell to its ___.","a": "Row total","lvl": 1,"choices": ["Row total","Column total","Grand total"],"steps": ["A row relative frequency looks across one row of the table.","You divide each cell by the total for that row. What is that total called?"]},{"id": "8.22-01","std": "8.22","q": "A segment is 5 cm long. After a rotation, how long is it?","a": "5 cm","lvl": 1,"also": ["5"],"steps": ["A rotation turns a figure. It doesn't stretch or shrink it.","So does the length change?"]},{"id": "8.22-02","std": "8.22","q": "An angle is 72°. After a reflection, what is its measure?","a": "72°","lvl": 1,"also": ["72"],"steps": ["A reflection flips a figure. It doesn't change angles.","So does the angle change?"]},{"id": "8.22-03","std": "8.22","q": "Two parallel lines are translated. Are the images parallel?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A translation slides every point the same way.","Lines that never meet, slid the same way, still never meet. So are they still parallel?"]},{"id": "8.22-04","std": "8.22","q": "Do rigid motions change size or shape?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["Rigid motions are slides, flips and turns.","Does sliding, flipping or turning a shape change its size or shape?"]},{"id": "8.22-05","std": "8.22","q": "Triangle ABC is reflected and then translated to triangle DEF. Are the triangles congruent?","a": "Yes","lvl": 1,"part": "a","choices": ["Yes","No"],"steps": ["Reflections and translations are rigid motions. They keep size and shape.","Same size and same shape means congruent."]},{"id": "8.22-06","std": "8.22","q": "Which is NOT a rigid motion? A. Rotation  B. Reflection  C. Dilation  D. Translation","a": "C","lvl": 2,"choices": ["A","B","C","D"],"steps": ["Rigid motions keep the same size.","Which choice makes a figure bigger or smaller?"]},{"id": "8.22-07","std": "8.22","q": "Square A has sides 4. Square B has sides 6. Can rigid motions map A onto B?","a": "No (they are different sizes)","lvl": 2,"part": "a","also": ["no"],"steps": ["Rigid motions keep the same size.","Sides of 4 and sides of 6 are different sizes. Can a slide, flip or turn change that?"]},{"id": "8.22-08","std": "8.22","q": "Triangle P is at (1, 1), (3, 1), (1, 4). Triangle Q is at (4, 3), (6, 3), (4, 6). Describe a rigid motion that maps P onto Q.","a": "Translate 3 right and 2 up","lvl": 3,"part": "a","also": ["(x + 3, y + 2)"],"steps": ["Match a pair of corners: (1, 1) goes to (4, 3).","How far right did it move: 4 − 1? How far up: 3 − 1?","Check another corner with the same move."]},{"id": "8.23-01","std": "8.23","q": "Translate (2, −3) 4 units left and 5 units up.","a": "(−2, 2)","lvl": 1,"steps": ["Left changes x: subtract 4 from x. Up changes y: add 5 to y.","x: 2 − 4. y: −3 + 5."]},{"id": "8.23-02","std": "8.23","q": "Reflect (3, 7) over the x-axis.","a": "(3, −7)","lvl": 1,"steps": ["Reflecting over the x-axis keeps x and changes the sign of y.","(x, y) becomes (x, −y)."]},{"id": "8.23-03","std": "8.23","q": "Reflect (−4, 2) over the y-axis.","a": "(4, 2)","lvl": 1,"steps": ["Reflecting over the y-axis keeps y and changes the sign of x.","(x, y) becomes (−x, y)."]},{"id": "8.23-04","std": "8.23","q": "Rotate (2, 5) 90° counterclockwise about the origin.","a": "(−5, 2)","lvl": 2,"steps": ["Rule for 90° counterclockwise: (x, y) becomes (−y, x).","Here x = 2 and y = 5. Put them into the rule."]},{"id": "8.23-05","std": "8.23","q": "Rotate (3, −1) 180° about the origin.","a": "(−3, 1)","lvl": 2,"steps": ["Rule for 180°: (x, y) becomes (−x, −y).","Change the sign of both numbers."]},{"id": "8.23-06","std": "8.23","q": "Dilate (4, −6) by a scale factor of {1/2} centered at the origin.","a": "(2, −3)","lvl": 2,"steps": ["A dilation multiplies both coordinates by the scale factor.","Multiply: {1/2} × 4 and {1/2} × (−6)."]},{"id": "8.23-07","std": "8.23","q": "Dilate (−3, 2) by a scale factor of 3 centered at the origin.","a": "(−9, 6)","lvl": 1,"steps": ["A dilation multiplies both coordinates by the scale factor.","Multiply: 3 × (−3) and 3 × 2."]},{"id": "8.23-08","std": "8.23","q": "Rotate (−1, 4) 90° clockwise about the origin.","a": "(4, 1)","lvl": 3,"steps": ["Rule for 90° clockwise: (x, y) becomes (y, −x).","Here x = −1 and y = 4. Put them into the rule."]},{"id": "8.23-09","std": "8.23","q": "What rule describes a translation 6 left and 2 down?","a": "(x − 6, y − 2)","lvl": 2,"steps": ["Left changes x by subtracting. Down changes y by subtracting.","Write it as (x − left, y − down)."]},{"id": "8.23-10","std": "8.23","q": "A point (x, y) becomes (y, −x). What transformation is this?","a": "A 90° clockwise rotation about the origin","lvl": 3,"also": ["90° clockwise rotation","rotation 90 clockwise"],"steps": ["Try a point: (1, 0) becomes (0, −1).","(1, 0) is on the right. (0, −1) is below. Which way did it turn, and how far?"]},{"id": "8.24-01","std": "8.24","q": "Triangle A has sides 3, 4, 5. Triangle B has sides 6, 8, 10. Are they similar? What is the scale factor from A to B?","a": "Yes, scale factor 2","lvl": 1,"also": ["2","yes"],"steps": ["Divide matching sides: 6 ÷ 3, 8 ÷ 4, 10 ÷ 5.","If every ratio is the same, the triangles are similar, and that ratio is the scale factor."]},{"id": "8.24-02","std": "8.24","q": "A rectangle 2 by 5 is dilated by a factor of 3. What are the new dimensions?","a": "6 by 15","lvl": 1,"steps": ["A dilation multiplies every side by the scale factor.","Multiply each side by 3: 2 × 3 and 5 × 3."]},{"id": "8.24-03","std": "8.24","q": "Are congruent figures also similar?","a": "Yes (scale factor 1)","lvl": 2,"choices": ["Yes (scale factor 1)","No"],"steps": ["Similar means same shape. Congruent means same shape and same size.","Same size is a scale factor of 1. Is that still the same shape?"]},{"id": "8.24-04","std": "8.24","q": "A figure is dilated by {1/2}, then rotated 90°. Is the image similar to the original?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A dilation changes the size but keeps the shape.","A rotation keeps the size and the shape. Is the shape still the same?"]},{"id": "8.24-05","std": "8.24","q": "Rectangle 4 by 6 and rectangle 6 by 8. Are they similar?","a": "No ({4/6} is not equal to {6/8})","lvl": 2,"also": ["no"],"steps": ["Compare short sides: 4 and 6. Compare long sides: 6 and 8.","Write each as a fraction: {4/6} and {6/8}. Simplify. Are they equal?"]},{"id": "8.24-06","std": "8.24","q": "Triangle (0, 0), (2, 0), (0, 4) maps to (0, 0), (6, 0), (0, 12). Describe the transformation.","a": "A dilation by a scale factor of 3 centered at the origin","lvl": 2,"also": ["dilation by 3","scale factor 3"],"steps": ["Compare matching points: (2, 0) goes to (6, 0), and (0, 4) goes to (0, 12).","Each coordinate was multiplied by the same number. What number? That's a dilation."]},{"id": "8.24-07","std": "8.24","q": "Two triangles have angles 40°, 60°, 80° and 40°, 60°, 80°. Are they similar?","a": "Yes","lvl": 2,"choices": ["Yes","No"],"steps": ["Similar triangles have all the same angles.","Compare the angles. Do they all match?"]},{"id": "8.24-08","std": "8.24","q": "Similar triangles: one has sides 5, 7, 9 and the other's shortest side is 15. Find its longest side.","a": "27","lvl": 3,"steps": ["Find the scale factor from the shortest sides: 15 ÷ 5.","Multiply the longest side, 9, by the scale factor."]},{"id": "8.25-01","std": "8.25","q": "Two parallel lines are cut by a transversal. One angle is 65°. Find its corresponding angle.","a": "65°","lvl": 1,"also": ["65"],"steps": ["Corresponding angles are in the same spot at each crossing.","When the lines are parallel, corresponding angles are equal."]},{"id": "8.25-02","std": "8.25","q": "Two parallel lines are cut by a transversal. One angle is 110°. Find its alternate interior angle.","a": "110°","lvl": 1,"also": ["110"],"steps": ["Alternate interior angles are between the parallel lines, on opposite sides of the transversal.","When the lines are parallel, alternate interior angles are equal."]},{"id": "8.25-03","std": "8.25","q": "Two parallel lines are cut by a transversal. Same-side interior angles are (3x)° and (2x + 30)°. Find x.","a": "x = 30","lvl": 3,"steps": ["Same-side interior angles add up to 180°: 3x + 2x + 30 = 180.","Combine like terms: 5x + 30 = 180.","Subtract 30 on both sides, then divide by 5."]},{"id": "8.25-04","std": "8.25","q": "Alternate exterior angles are (4x − 10)° and (2x + 40)°. Find x.","a": "x = 25","lvl": 2,"steps": ["Alternate exterior angles are equal: 4x − 10 = 2x + 40.","Subtract 2x on both sides, then add 10. Now it's 2x = 50.","Divide both sides by 2."]},{"id": "8.25-05","std": "8.25","q": "Corresponding angles are (5x + 5)° and 80°. Find x.","a": "x = 15","lvl": 2,"steps": ["Corresponding angles are equal: 5x + 5 = 80.","Subtract 5 on both sides, then divide by 5."]},{"id": "8.25-06","std": "8.25","q": "Two angles of a triangle are 48° and 67°. Find the third angle.","a": "65°","lvl": 1,"part": "a","also": ["65"],"steps": ["The three angles of a triangle add up to 180°.","Add the two angles you know: 48 + 67.","Subtract that from 180."]},{"id": "8.25-07","std": "8.25","q": "The angles of a triangle are (x + 3)°, (3x + 2)° and (2x + 1)°. Find x.","a": "x = 29","lvl": 2,"part": "a","steps": ["Add the angles and set them equal to 180: (x + 3) + (3x + 2) + (2x + 1) = 180.","Combine like terms: 6x + 6 = 180.","Subtract 6 on both sides, then divide by 6."]},{"id": "8.25-08","std": "8.25","q": "An isosceles triangle has a vertex angle of 40°. Find each base angle.","a": "70°","lvl": 2,"part": "a","also": ["70"],"steps": ["Take away the vertex angle: 180 − 40.","The two base angles are equal, so split what's left in half."]},{"id": "8.25-09","std": "8.25","q": "The angles of a triangle are in the ratio 2 : 3 : 4. Find the largest angle.","a": "80°","lvl": 3,"part": "a","also": ["80"],"steps": ["Write the angles as 2x, 3x and 4x. They add up to 180: 9x = 180.","Solve for x.","The largest angle is 4x."]},{"id": "8.25-10","std": "8.25","q": "An exterior angle of a triangle is 120°. One remote interior angle is 50°. Find the other.","a": "70°","lvl": 3,"part": "a","also": ["70"],"steps": ["An exterior angle equals the two remote interior angles added together.","So the missing angle is 120 minus the one you know."]},{"id": "8.26-01","std": "8.26","q": "Write the Pythagorean Theorem.","a": "a² + b² = c²","lvl": 1,"steps": ["It connects the three sides of a right triangle. The legs are a and b. The hypotenuse is c.","Square each leg and add them. That equals the hypotenuse squared."]},{"id": "8.26-02","std": "8.26","q": "In a right triangle, what is the hypotenuse?","a": "The side across from the right angle (the longest side)","lvl": 1,"also": ["longest side"],"steps": ["Find the right angle in the triangle.","The side across from it has a special name, and it's always the longest side."]},{"id": "8.26-03","std": "8.26","q": "Is a triangle with sides 5, 12, 13 a right triangle?","a": "Yes (25 + 144 = 169)","lvl": 1,"also": ["yes"],"steps": ["Square the two short sides: 5² and 12². Add them.","Square the longest side: 13². If the two answers match, it's a right triangle."]},{"id": "8.26-04","std": "8.26","q": "Is a triangle with sides 6, 7, 9 a right triangle?","a": "No (36 + 49 = 85, not 81)","lvl": 2,"also": ["no"],"steps": ["Square the two short sides: 6² and 7². Add them.","Square the longest side: 9². Do the two answers match?"]},{"id": "8.26-05","std": "8.26","q": "Is a triangle with sides 8, 15, 17 a right triangle?","a": "Yes (64 + 225 = 289)","lvl": 2,"also": ["yes"],"steps": ["Square the two short sides: 8² and 15². Add them.","Square the longest side: 17². Do the two answers match?"]},{"id": "8.26-06","std": "8.26","q": "Squares are drawn on the sides of a right triangle. The two small squares have areas 9 and 16. What is the area of the big square?","a": "25","lvl": 2,"steps": ["The squares' areas are a², b² and c².","a² + b² = c², so add the two small areas."]},{"id": "8.26-07","std": "8.26","q": "Is a triangle with sides 1.5, 2 and 2.5 a right triangle?","a": "Yes (2.25 + 4 = 6.25)","lvl": 3,"also": ["yes"],"steps": ["Square the two short sides: 1.5² and 2². Add them.","Square the longest side: 2.5². Do the two answers match?"]},{"id": "8.26-08","std": "8.26","q": "Which side goes in c when you check sides 9, 40, 41?","a": "41 (the longest side)","lvl": 1,"also": ["41"],"steps": ["c is always the hypotenuse.","The hypotenuse is the longest side. Which number is biggest?"]},{"id": "8.27-01","std": "8.27","q": "Find the distance between (1, 2) and (4, 6).","a": "5","lvl": 1,"steps": ["Make a right triangle. Across: 4 − 1. Up: 6 − 2.","Use a² + b² = c² with those two legs.","Take the square root of the sum."]},{"id": "8.27-02","std": "8.27","q": "Find the distance between (−2, −1) and (4, 7).","a": "10","lvl": 2,"steps": ["Across: 4 − (−2). Up: 7 − (−1).","Use a² + b² = c² with those two legs.","Take the square root of the sum."]},{"id": "8.27-03","std": "8.27","q": "Find the distance between (0, 0) and (5, 12).","a": "13","lvl": 1,"steps": ["Across: 5 − 0. Up: 12 − 0.","Use a² + b² = c²: 5² + 12².","Take the square root of the sum."]},{"id": "8.27-04","std": "8.27","q": "Find the distance between (−3, 4) and (3, −4).","a": "10","lvl": 2,"steps": ["Across: 3 − (−3). Down: 4 − (−4).","Use a² + b² = c² with those two legs.","Take the square root of the sum."]},{"id": "8.27-05","std": "8.27","q": "Find the distance between (1, 1) and (4, 3). Round to the nearest tenth.","a": "3.6","lvl": 2,"also": ["√13"],"steps": ["Across: 4 − 1. Up: 3 − 1.","Use a² + b² = c²: 3² + 2².","Take the square root and round to the nearest tenth."]},{"id": "8.27-06","std": "8.27","q": "Find the distance between (−2, 3) and (2, −1). Round to the nearest tenth.","a": "5.7","lvl": 3,"also": ["√32","4√2"],"steps": ["Across: 2 − (−2). Down: 3 − (−1).","Use a² + b² = c²: 4² + 4².","Take the square root and round to the nearest tenth."]},{"id": "8.27-07","std": "8.27","q": "Points A(2, 1) and B(2, 9) are on a vertical line. How far apart are they?","a": "8","lvl": 1,"steps": ["Both points have x = 2, so only y changes.","Distance = 9 − 1."]},{"id": "8.27-08","std": "8.27","q": "On a map grid, school is at (0, 0) and the park is at (6, 8). Each unit is 1 block. How far is the park in a straight line?","a": "10 blocks","lvl": 2,"also": ["10"],"steps": ["Across: 6 blocks. Up: 8 blocks. Those are the legs.","Use a² + b² = c²: 6² + 8².","Take the square root of the sum."]},{"id": "8.28-01","std": "8.28","q": "The legs of a right triangle are 6 and 8. Find the hypotenuse.","a": "10","lvl": 1,"steps": ["Use a² + b² = c². The legs are 6 and 8.","Square them and add: 36 + 64.","Take the square root of the sum."]},{"id": "8.28-02","std": "8.28","q": "A right triangle has a hypotenuse of 13 and a leg of 5. Find the other leg.","a": "12","lvl": 1,"steps": ["Use a² + b² = c². The hypotenuse is the longest side, so c = 13.","Put in what you know: 5² + b² = 13², so 25 + b² = 169.","Subtract 25, then take the square root."]},{"id": "8.28-03","std": "8.28","q": "The legs are 7 and 24. Find the hypotenuse.","a": "25","lvl": 2,"steps": ["Use a² + b² = c². The legs are 7 and 24.","Square them and add: 49 + 576.","Take the square root of the sum."]},{"id": "8.28-04","std": "8.28","q": "A 10-foot ladder leans against a wall. Its base is 6 feet from the wall. How high does it reach?","a": "8 feet","lvl": 2,"also": ["8"],"steps": ["The ladder is the hypotenuse: c = 10. The ground distance is a leg: 6.","6² + h² = 10², so 36 + h² = 100.","Subtract 36, then take the square root."]},{"id": "8.28-05","std": "8.28","q": "A TV screen is 32 in wide and 18 in tall. Find the diagonal to the nearest inch.","a": "37 in","lvl": 3,"also": ["37"],"steps": ["The width and height are the legs. The diagonal is the hypotenuse.","32² + 18² = 1024 + 324.","Take the square root and round to the nearest inch."]},{"id": "8.28-06","std": "8.28","q": "The legs of a right triangle are 4 and 5. Find the hypotenuse to the nearest tenth.","a": "6.4","lvl": 2,"also": ["√41"],"steps": ["Use a² + b² = c². The legs are 4 and 5.","Square them and add: 16 + 25.","Take the square root and round to the nearest tenth."]},{"id": "8.28-07","std": "8.28","q": "A soccer field is 100 yd by 60 yd. How long is the diagonal to the nearest yard?","a": "117 yd","lvl": 3,"also": ["117"],"steps": ["The length and width are the legs. The diagonal is the hypotenuse.","100² + 60² = 10,000 + 3,600.","Take the square root and round to the nearest yard."]},{"id": "8.28-08","std": "8.28","q": "A square has a diagonal of 10 cm. Find the side length to the nearest tenth.","a": "7.1 cm","lvl": 3,"also": ["7.1","√50","5√2"],"steps": ["A square's diagonal makes a right triangle with two equal legs, s and s.","s² + s² = 10², so 2s² = 100. Divide by 2.","Take the square root and round to the nearest tenth."]},{"id": "8.28-09","std": "8.28","q": "You walk 9 blocks north and 12 blocks east. How far are you from where you started in a straight line?","a": "15 blocks","lvl": 2,"also": ["15"],"steps": ["North and east make a right angle. The legs are 9 and 12.","Square them and add: 81 + 144.","Take the square root of the sum."]},{"id": "8.29-01","std": "8.29","q": "A cone and a cylinder have the same radius and height. How many cones of water fill the cylinder?","a": "3","lvl": 1,"steps": ["A cone's volume is {1/3} of a cylinder's with the same radius and height.","If one cone fills {1/3} of the cylinder, how many cones fill all of it?"]},{"id": "8.29-02","std": "8.29","q": "A cone has the same radius and height as a cylinder with volume 90 cm³. What is the cone's volume?","a": "30 cm³","lvl": 1,"also": ["30"],"steps": ["A cone holds {1/3} of a cylinder with the same radius and height.","Find {1/3} of 90."]},{"id": "8.29-03","std": "8.29","q": "A sphere fits exactly inside a cylinder (same radius, height = diameter). What fraction of the cylinder's volume is the sphere?","a": "{2/3}","lvl": 2,"steps": ["Cylinder with height 2r: V = πr² × 2r = 2πr³. Sphere: V = {4/3}πr³.","Divide the sphere by the cylinder: {4/3}πr³ ÷ 2πr³. The πr³ cancels.","Find {4/3} ÷ 2."]},{"id": "8.29-04","std": "8.29","q": "A cylinder with radius r and height 2r has volume 2πr³. What is the volume of a sphere with radius r?","a": "{4/3}πr³","lvl": 2,"steps": ["A sphere that fits inside this cylinder holds {2/3} of it.","Find {2/3} × 2πr³."]},{"id": "8.29-05","std": "8.29","q": "A cylinder holds 600 mL. A cone with the same radius and height is filled and poured in. How many times can you pour before the cylinder is full?","a": "3","lvl": 1,"steps": ["A cone holds {1/3} of a cylinder with the same radius and height.","How many thirds make one whole?"]},{"id": "8.29-06","std": "8.29","q": "A cylinder (height = diameter) holds 150 cm³. What is the volume of the sphere that fits inside?","a": "100 cm³","lvl": 3,"also": ["100"],"steps": ["The sphere that fits inside holds {2/3} of the cylinder.","Find {2/3} × 150."]},{"id": "8.29-07","std": "8.29","q": "Why is a cone's volume {1/3} of a cylinder's with the same base and height?","a": "Three cones of water fill the cylinder exactly","lvl": 2,"steps": ["Think about filling a cylinder with water from a cone with the same base and height.","How many cones does it take? That's why the fraction is {1/3}."]},{"id": "8.29-08","std": "8.29","q": "Write the formula for the volume of a cone.","a": "V = {1/3}πr²h","lvl": 1,"also": ["1/3πr²h"],"steps": ["A cylinder is V = πr²h.","A cone holds {1/3} of a cylinder with the same base and height. Put {1/3} in front."]},{"id": "8.30-01","std": "8.30","q": "Find the volume of a cylinder with radius 3 cm and height 10 cm. Use 3.14.","a": "282.6 cm³","lvl": 1,"also": ["282.6"],"steps": ["Cylinder: V = πr²h.","Square the radius: 3² = 9. Then multiply 3.14 × 9 × 10."]},{"id": "8.30-02","std": "8.30","q": "Find the volume of a cylinder with radius 4 in and height 5 in. Leave it in terms of π.","a": "80π in³","lvl": 1,"also": ["80π"],"steps": ["Cylinder: V = πr²h.","Square the radius: 4² = 16. Multiply by the height, 5, and keep π."]},{"id": "8.30-03","std": "8.30","q": "Find the volume of a cone with radius 3 ft and height 4 ft. Leave it in terms of π.","a": "12π ft³","lvl": 2,"also": ["12π"],"steps": ["Cone: V = {1/3}πr²h.","Square the radius: 3² = 9. Multiply 9 × 4, take {1/3} of it, and keep π."]},{"id": "8.30-04","std": "8.30","q": "Find the volume of a sphere with radius 3 m. Leave it in terms of π.","a": "36π m³","lvl": 2,"also": ["36π"],"steps": ["Sphere: V = {4/3}πr³.","Cube the radius: 3³ = 27. Multiply by {4/3} and keep π."]},{"id": "8.30-05","std": "8.30","q": "Find the volume of a cone with diameter 10 cm and height 9 cm. Use 3.14.","a": "235.5 cm³","lvl": 2,"also": ["235.5"],"steps": ["The radius is half the diameter: 10 ÷ 2 = 5.","Cone: V = {1/3}πr²h = {1/3} × 3.14 × 25 × 9.","Do 25 × 9, take {1/3}, then multiply by 3.14."]},{"id": "8.30-06","std": "8.30","q": "Find the volume of a sphere with diameter 6 in. Use 3.14 and round to the nearest tenth.","a": "113.0 in³","lvl": 2,"also": ["113.0"],"steps": ["The radius is half the diameter: 6 ÷ 2 = 3.","Sphere: V = {4/3}πr³ = {4/3} × 3.14 × 27.","Do {4/3} × 27 first, then multiply by 3.14. Round to the nearest tenth."]},{"id": "8.30-07","std": "8.30","q": "A can is 12 cm tall with a radius of 4 cm. How much does it hold? Use 3.14.","a": "602.88 cm³","lvl": 2,"also": ["602.88"],"steps": ["A can is a cylinder: V = πr²h.","Square the radius: 4² = 16. Then multiply 3.14 × 16 × 12."]},{"id": "8.30-08","std": "8.30","q": "A cylinder has volume 72π and radius 3. Find its height.","a": "8","lvl": 3,"steps": ["Cylinder: V = πr²h, so 72π = π × 3² × h.","3² = 9, so 72π = 9πh.","Divide both sides by 9π."]},{"id": "8.30-09","std": "8.30","q": "A cone-shaped cup has radius 2 in and height 6 in. A cylinder cup has radius 2 in and height 6 in. How many cone cups fill the cylinder cup?","a": "3","lvl": 1,"steps": ["Same radius and same height: a cone holds {1/3} of the cylinder.","How many thirds make one whole cylinder?"]},{"id": "8.30-10","std": "8.30","q": "An ice cream cone (radius 1 in, height 5 in) has a half sphere of ice cream (radius 1 in) on top. Find the total volume in terms of π.","a": "{7/3}π in³","lvl": 3,"also": ["7/3π","2{1/3}π"],"steps": ["Cone: V = {1/3}π(1²)(5) = {5/3}π.","Half sphere: V = {1/2} × {4/3}π(1³) = {2/3}π.","Add the two parts. Keep π."]},{"id": "8.25-11","std": "8.25","q": "A triangle has interior angles measuring 48° and 75°. What is the measure of the third interior angle?","a": "57°","lvl": 1,"part": "a","choices": ["57°","67°","123°","237°"]},{"id": "8.25-12","std": "8.25","q": "In a right triangle, one of the acute angles measures 34°. What is the measure of the other acute angle?","a": "56°","lvl": 1,"part": "a","choices": ["56°","66°","124°","146°"]},{"id": "8.25-13","std": "8.25","q": "Which set of three angle measures can form a triangle?","a": "38°, 64°, 78°","lvl": 1,"part": "a","choices": ["38°, 64°, 78°","45°, 45°, 80°","55°, 65°, 70°","90°, 50°, 50°"]},{"id": "8.25-14","std": "8.25","q": "To show that the interior angles of triangle ABC add up to 180°, Maya draws a line through vertex B that is parallel to side AC. Which angle relationship explains why the two outer angles formed on the parallel line at vertex B are congruent to angles A and C?","a": "Alternate interior angles are congruent.","lvl": 2,"part": "a","choices": ["Vertical angles are supplementary.","Alternate interior angles are congruent.","Complementary angles add up to 180°.","Same-side interior angles are congruent."]},{"id": "8.25-15","std": "8.25","q": "A wooden roof truss is shaped like an isosceles triangle with a top vertex angle of 116°. What is the measure of each of the two equal base angles?","a": "32°","lvl": 2,"part": "a","choices": ["32°","58°","64°","122°"]},{"id": "8.25-16","std": "8.25","q": "The interior angles of a triangle measure (2x + 10)°, 54°, and 68°. What is the value of x?","a": "24","lvl": 2,"part": "a","choices": ["24","34","48","58"]},{"id": "8.25-17","std": "8.25","q": "In triangle PQR, angle P measures (3x − 5)°, angle Q measures (2x + 15)°, and angle R measures (x + 20)°. What is the measure of the largest angle in triangle PQR?","a": "70°","lvl": 3,"part": "a","choices": ["25°","65°","70°","80°"]},{"id": "8.25-18","std": "8.25","q": "The interior angles of a triangle are in the ratio 2 : 3 : 7. What is the difference between the largest angle and the smallest angle of the triangle?","a": "75°","lvl": 3,"part": "a","choices": ["15°","60°","75°","105°"]},{"id": "8.25-19","std": "8.25","q": "Triangle JKL is divided into two smaller triangles, JKM and LKM, by drawing segment KM from vertex K to point M on side JL. Angle J measures 42°, angle JKM measures 53°, and angle L measures 61°. What is the measure of angle LKM?","a": "24°","lvl": 3,"part": "a","also": ["24","24 degrees"]},{"id": "8.1-12","std": "8.1","q": "Which of the following numbers is irrational?","a": "√15","lvl": 1,"choices": ["√15","0.75","0.333...","−{4/9}"]},{"id": "8.1-13","std": "8.1","q": "Write the rational number {3/8} as a decimal.","a": "0.375","lvl": 1,"part": "a","choices": ["0.375","0.38","0.83","2.67"]},{"id": "8.1-14","std": "8.1","q": "Which fraction is equivalent to the repeating decimal 0.777...?","a": "{7/9}","lvl": 1,"part": "b","choices": ["{7/10}","{7/99}","{7/9}","{1/7}"]},{"id": "8.1-15","std": "8.1","q": "Convert the repeating decimal 0.454545... into a fraction in simplest form.","a": "{5/11}","lvl": 2,"part": "b","choices": ["{9/20}","{45/100}","{5/11}","{45/90}"]},{"id": "8.1-16","std": "8.1","q": "Which fraction produces a repeating decimal expansion?","a": "{7/12}","lvl": 2,"part": "a","choices": ["{7/12}","{9/16}","{11/20}","{13/25}"]},{"id": "8.1-17","std": "8.1","q": "Consider the set of numbers: {π, 3.14, −7, √36, √20}. How many of these numbers are rational?","a": "3","lvl": 2,"choices": ["2","3","4","5"]},{"id": "8.1-18","std": "8.1","q": "Convert the repeating decimal 1.2333... (where only the 3 repeats) into a fraction in simplest form.","a": "{37/30}","lvl": 3,"part": "b","choices": ["{37/90}","{123/99}","{37/30}","{123/100}"]},{"id": "8.1-19","std": "8.1","q": "A student claims that {22/7} and π are both irrational because their decimals go on forever without ending. Which statement correctly evaluates the student's claim?","a": "The student is incorrect because {22/7} is a ratio of two integers and has a repeating decimal pattern, making it rational.","lvl": 3,"choices": ["The student is correct because fractions with 7 in the denominator are always irrational.","The student is correct because neither decimal ever terminates.","The student is incorrect because both {22/7} and π are rational approximations.","The student is incorrect because {22/7} is a ratio of two integers and has a repeating decimal pattern, making it rational."]},{"id": "8.1-20","std": "8.1","q": "Express the sum of 0.444... and 0.1666... (where only the 6 repeats) as a single fraction in simplest form.","a": "{11/18}","lvl": 3,"part": "b","choices": ["{11/18}","{3/5}","{61/100}","{61/99}"]},{"id": "8.2-10","std": "8.2","q": "Between which two consecutive whole numbers does √53 lie?","a": "7 and 8","lvl": 1,"choices": ["6 and 7","7 and 8","8 and 9","26 and 27"]},{"id": "8.2-11","std": "8.2","q": "Which whole number is closest to √85?","a": "9","lvl": 1,"choices": ["8","9","10","42"]},{"id": "8.2-12","std": "8.2","q": "Which symbol makes the statement true? (√30) ___ 5.2","a": ">","lvl": 1,"choices": ["=","≤","<",">"]},{"id": "8.2-13","std": "8.2","q": "Which number is closest to 6.5 on a number line?","a": "√42","lvl": 2,"choices": ["√47","√42","√38","√50"]},{"id": "8.2-14","std": "8.2","q": "Order the following numbers from least to greatest: 4.5, √18, {17/4}, √23.","a": "√18, {17/4}, 4.5, √23","lvl": 2,"choices": ["√18, {17/4}, 4.5, √23","√18, 4.5, {17/4}, √23","{17/4}, √18, 4.5, √23","{17/4}, 4.5, √18, √23"]},{"id": "8.2-15","std": "8.2","q": "Estimate the value of √110 to the nearest tenth.","a": "10.5","lvl": 2,"choices": ["10.1","10.5","10.8","11.0"]},{"id": "8.2-16","std": "8.2","q": "A square garden has an area of 70 square feet. Between which two tenths of a foot does the side length of the garden fall?","a": "8.3 feet and 8.4 feet","lvl": 3,"choices": ["8.1 feet and 8.2 feet","8.3 feet and 8.4 feet","8.5 feet and 8.6 feet","8.7 feet and 8.8 feet"]},{"id": "8.2-17","std": "8.2","q": "Point P on a number line represents the value (2π) + 1. Which statement best describes the location of Point P?","a": "It is between 7.2 and 7.3.","lvl": 3,"choices": ["It is between 8.2 and 8.3.","It is between 7.2 and 7.3.","It is between 7.5 and 7.6.","It is between 6.2 and 6.3."]},{"id": "8.2-18","std": "8.2","q": "Find an integer n such that 4.2 < √n < 4.3.","a": "18","lvl": 3,"choices": ["16","17","18","19"]},{"id": "8.3-13","std": "8.3","q": "Simplify the expression: 4³ · 4⁵","a": "4⁸","lvl": 1,"choices": ["4⁸","16⁸","4²","4¹⁵"]},{"id": "8.3-14","std": "8.3","q": "Which expression is equivalent to 5⁻³?","a": "{1/125}","lvl": 1,"choices": ["−125","{1/125}","{1/15}","−15"]},{"id": "8.3-15","std": "8.3","q": "What is the value of (9⁰) + (3²)?","a": "10","lvl": 1,"choices": ["6","9","10","18"]},{"id": "8.3-16","std": "8.3","q": "Simplify the expression: {x⁷ · x⁻²/x³}","a": "x²","lvl": 2,"choices": ["x⁶","x²","x⁸","x¹²"]},{"id": "8.3-17","std": "8.3","q": "Which expression is equivalent to (2³)⁻²?","a": "{1/64}","lvl": 2,"choices": ["−64","2","{1/32}","{1/64}"]},{"id": "8.3-18","std": "8.3","q": "Rewrite the expression (3a⁴)² using positive exponents.","a": "9a⁸","lvl": 2,"choices": ["6a⁸","9a⁶","3a⁶","9a⁸"]},{"id": "8.3-19","std": "8.3","q": "Find the value of k that makes the equation true: {6^k · 6⁻⁴/6²} = 6⁵","a": "11","lvl": 3,"choices": ["3","7","9","11"]},{"id": "8.3-20","std": "8.3","q": "A student simplified (5² · 5⁻⁶) as 25⁻⁴. Identify the error the student made and give the correct simplified form with a positive exponent.","a": "The student multiplied the bases instead of keeping the base 5; the correct answer is {1/5⁴}.","lvl": 3,"choices": ["The student made no error; 25⁻⁴ is equivalent to {1/5⁸}.","The student multiplied the bases instead of keeping the base 5; the correct answer is {1/5⁴}.","The student subtracted the exponents instead of adding; the correct answer is 25⁸.","The student should have multiplied the exponents; the correct answer is {1/5¹²}."]},{"id": "8.3-21","std": "8.3","q": "Which expression is equivalent to {4⁻² · 2⁵/8⁰}?","a": "2","lvl": 3,"choices": ["8","4","{1/2}","2"]},{"id": "8.4-13","std": "8.4","q": "Evaluate: √169","a": "13","lvl": 1,"part": "a","choices": ["12","13","14","84.5"]},{"id": "8.4-14","std": "8.4","q": "Evaluate: ∛64","a": "4","lvl": 1,"part": "a","choices": ["4","8","16","21.3"]},{"id": "8.4-15","std": "8.4","q": "Solve for x: x² = 121","a": "x = 11 or x = −11","lvl": 1,"choices": ["x = 11 only","x = 14,641","x = 11 or x = −11","x = 60.5"]},{"id": "8.4-16","std": "8.4","q": "Solve for p: p³ = 343","a": "p = 7","lvl": 2,"choices": ["p = 114.3","p = 7","p = 18.5","p = 7 or p = −7"]},{"id": "8.4-17","std": "8.4","q": "Which equation has solutions that are irrational numbers?","a": "x² = 50","lvl": 2,"part": "b","choices": ["x² = 225","x² = 144","x² = 50","x² = 36"]},{"id": "8.4-18","std": "8.4","q": "What is the value of (√196) − (∛125)?","a": "9","lvl": 2,"part": "a","choices": ["3","9","11","19"]},{"id": "8.4-19","std": "8.4","q": "A cube-shaped storage box has a volume of 512 cubic inches. A square picture frame has an area of 144 square inches. How much longer is one side of the picture frame than one edge of the storage box?","a": "4 inches","lvl": 3,"choices": ["2 inches","4 inches","8 inches","12 inches"]},{"id": "8.4-20","std": "8.4","q": "Explain why the equation x² = 45 has two real solutions, and classify whether those solutions are rational or irrational.","a": "Both +√45 and −√45 square to 45, and both are irrational because 45 is not a perfect square.","lvl": 3,"part": "b","choices": ["Both +√45 and −√45 square to 45, and both are rational because they can be written under a radical.","Both +√45 and −√45 square to 45, and both are irrational because 45 is not a perfect square.","It has one positive solution √45, which is rational because 45 is an odd integer.","It has two solutions, 22.5 and −22.5, which are rational."]},{"id": "8.4-21","std": "8.4","q": "Solve for y: 2y² + 7 = 207","a": "y = 10 or y = −10","lvl": 3,"choices": ["y = 100 or y = −100","y = 10 or y = −10","y = 50 or y = −50","y = 10 only"]},{"id": "8.5-09","std": "8.5","q": "Write 4,800,000 in scientific notation.","a": "4.8 × 10⁶","lvl": 1,"choices": ["4.8 × 10⁶","0.48 × 10⁷","48 × 10⁵","4.8 × 10⁻⁶"]},{"id": "8.5-10","std": "8.5","q": "Write 0.00032 in scientific notation.","a": "3.2 × 10⁻⁴","lvl": 1,"choices": ["3.2 × 10⁻⁴","3.2 × 10⁻³","32 × 10⁻⁵","3.2 × 10⁴"]},{"id": "8.5-11","std": "8.5","q": "Which number is greater: 6.1 × 10⁵ or 8.9 × 10⁴?","a": "6.1 × 10⁵","lvl": 1,"choices": ["6.1 × 10⁵","They are equal","Cannot be determined","8.9 × 10⁴"]},{"id": "8.5-12","std": "8.5","q": "The mass of a dust particle is about 7.5 × 10⁻¹⁰ kilograms, and the mass of a grain of sand is about 1.5 × 10⁻⁶ kilograms. About how many times heavier is the grain of sand than the dust particle?","a": "2,000 times heavier","lvl": 2,"choices": ["5 times heavier","200 times heavier","2,000 times heavier","20,000 times heavier"]},{"id": "8.5-13","std": "8.5","q": "Order the following numbers from least to greatest: 4.2 × 10⁻³, 9.1 × 10⁻⁴, 3.8 × 10⁻³, 1.2 × 10⁻².","a": "9.1 × 10⁻⁴, 3.8 × 10⁻³, 4.2 × 10⁻³, 1.2 × 10⁻²","lvl": 2,"choices": ["1.2 × 10⁻², 3.8 × 10⁻³, 4.2 × 10⁻³, 9.1 × 10⁻⁴","9.1 × 10⁻⁴, 3.8 × 10⁻³, 4.2 × 10⁻³, 1.2 × 10⁻²","9.1 × 10⁻⁴, 4.2 × 10⁻³, 3.8 × 10⁻³, 1.2 × 10⁻²","3.8 × 10⁻³, 4.2 × 10⁻³, 9.1 × 10⁻⁴, 1.2 × 10⁻²"]},{"id": "8.5-14","std": "8.5","q": "City A has a population of 2.4 × 10⁶ people. City B has a population of 600,000 people. How many times larger is City A's population than City B's population?","a": "4 times larger","lvl": 2,"choices": ["0.4 times larger","4 times larger","40 times larger","400 times larger"]},{"id": "8.5-15","std": "8.5","q": "A red blood cell is approximately 8 × 10⁻⁶ meters wide. A human hair is approximately 8 × 10⁻⁵ meters wide. A virus is approximately 1 × 10⁻⁷ meters wide. Which comparison is true?","a": "The human hair is 800 times wider than the virus.","lvl": 3,"choices": ["The human hair is 800 times wider than the virus.","The human hair is 80 times wider than the virus.","The red blood cell is 10 times wider than the human hair.","The virus is 8 times wider than the red blood cell."]},{"id": "8.5-16","std": "8.5","q": "Earth is approximately 9.3 × 10⁷ miles from the Sun, and Neptune is approximately 2.79 × 10⁹ miles from the Sun. Estimate how many times farther Neptune is from the Sun than Earth is.","a": "30 times farther","lvl": 3,"choices": ["0.3 times farther","3 times farther","30 times farther","300 times farther"]},{"id": "8.5-17","std": "8.5","q": "If n = 4.5 × 10⁸, between which two powers of 10 does 3n lie?","a": "10⁹ and 10¹⁰","lvl": 3,"choices": ["10⁸ and 10⁹","10⁹ and 10¹⁰","10⁷ and 10⁸","10²⁴ and 10²⁵"]},{"id": "8.6-12","std": "8.6","q": "Multiply: (3 × 10⁴) × (3 × 10⁶). Express your answer in scientific notation.","a": "9 × 10¹⁰","lvl": 1,"choices": ["6 × 10¹⁰","9 × 10²⁴","6 × 10²⁴","9 × 10¹⁰"]},{"id": "8.6-13","std": "8.6","q": "Divide: {8 × 10⁷/4 × 10²}. Express your answer in scientific notation.","a": "2 × 10⁵","lvl": 1,"choices": ["2 × 10⁹","32 × 10⁵","2 × 10⁵","4 × 10⁵"]},{"id": "8.6-14","std": "8.6","q": "A scientific calculator displays the result of a calculation as 5.4E-6. What is this number written in standard scientific notation?","a": "5.4 × 10⁻⁶","lvl": 1,"part": "b","choices": ["−5.4 × 10⁶","5.4⁻⁶","5.4 × 10⁶","5.4 × 10⁻⁶"]},{"id": "8.6-15","std": "8.6","q": "Multiply: (4 × 10⁵) × (5 × 10³). Express your answer in proper scientific notation.","a": "2 × 10⁹","lvl": 2,"choices": ["2 × 10⁹","20 × 10⁸","2 × 10⁸","9 × 10⁸"]},{"id": "8.6-16","std": "8.6","q": "Add: (3.4 × 10⁵) + (2.1 × 10⁴). Express your answer in scientific notation.","a": "3.61 × 10⁵","lvl": 2,"choices": ["3.61 × 10⁴","5.5 × 10⁹","5.5 × 10⁵","3.61 × 10⁵"]},{"id": "8.6-17","std": "8.6","q": "The thickness of a single sheet of paper is about 1 × 10⁻⁴ meters. Which unit of measurement is most appropriate to express this thickness without using scientific notation?","a": "Millimeters","lvl": 2,"part": "a","choices": ["Miles","Kilometers","Meters","Millimeters"]},{"id": "8.6-18","std": "8.6","q": "A factory produces 2.5 × 10⁴ cans of soup per day. If each can holds 300 milliliters of soup, how many total milliliters of soup does the factory produce in 4 days? Express your answer in scientific notation.","a": "3 × 10⁷ milliliters","lvl": 3,"choices": ["7.5 × 10⁶ milliliters","30 × 10⁷ milliliters","3 × 10⁶ milliliters","3 × 10⁷ milliliters"]},{"id": "8.6-19","std": "8.6","q": "Subtract: (6.2 × 10⁻³) − (4.5 × 10⁻⁴). Express your answer in scientific notation.","a": "5.75 × 10⁻³","lvl": 3,"choices": ["5.75 × 10⁻⁴","1.7 × 10⁻³","1.7 × 10⁻⁴","5.75 × 10⁻³"]},{"id": "8.6-20","std": "8.6","q": "On a calculator, multiplying 4.5E8 by 6.0E5 displays 2.7E14. Explain why the exponent on the calculator is 14 instead of 13.","a": "4.5 × 6.0 = 27, which is 2.7 × 10¹, adding 1 to the sum of the exponents (8 + 5 + 1 = 14).","lvl": 3,"part": "b","choices": ["The calculator rounded up because the number was too large.","8 + 5 equals 14 in scientific notation.","When multiplying in scientific notation, you always add 1 to the product of the exponents.","4.5 × 6.0 = 27, which is 2.7 × 10¹, adding 1 to the sum of the exponents (8 + 5 + 1 = 14)."]},{"id": "8.7-09","std": "8.7","q": "Which equation represents a proportional relationship between x and y?","a": "y = 4x","lvl": 1,"choices": ["y = 4x + 2","y = {4/x}","y = 4x","y = x²"]},{"id": "8.7-10","std": "8.7","q": "A table shows pairs (x, y): (1, 3), (2, 6), (3, 9), (4, 12). Is this relationship proportional?","a": "Yes, because the ratio {y/x} is constant at 3 for every pair.","lvl": 1,"choices": ["Yes, because the ratio {y/x} is constant at 3 for every pair.","Yes, because x increases by 1 each time.","No, because x and y are not equal.","No, because 0 is not shown in the table."]},{"id": "8.7-11","std": "8.7","q": "Which situation describes a non-proportional relationship?","a": "A gym charges a §25 sign-up fee plus §15 per month.","lvl": 1,"choices": ["Apples cost §2.50 per pound.","A gym charges a §25 sign-up fee plus §15 per month.","A printer prints 18 pages per minute.","A car travels at a constant speed of 60 miles per hour."]},{"id": "8.7-12","std": "8.7","q": "Examine the table of values: x = 2, y = 7; x = 4, y = 13; x = 6, y = 19. Determine whether the relationship is proportional and explain why.","a": "Non-proportional, because the ratios {y/x} ({7/2}, {13/4}, {19/6}) are not equal.","lvl": 2,"choices": ["Proportional, because y increases by 6 every time x increases by 2.","Proportional, because the rate of change is a constant 3.","Non-proportional, because the numbers are odd.","Non-proportional, because the ratios {y/x} ({7/2}, {13/4}, {19/6}) are not equal."]},{"id": "8.7-13","std": "8.7","q": "Service 1 charges §12 per month with no sign-up fee. Service 2 charges a §10 activation fee and §12 per month. Which statement is true?","a": "Only the first service represents a proportional relationship.","lvl": 2,"choices": ["Only the first service represents a proportional relationship.","Both services represent proportional relationships because both charge §12 per month.","Neither service represents a proportional relationship.","Only the second service represents a proportional relationship."]},{"id": "8.7-14","std": "8.7","q": "In a proportional relationship, when x = 5, y = 17.5. What is the value of y when x = 8?","a": "28","lvl": 2,"choices": ["20.5","25","28","35"]},{"id": "8.7-15","std": "8.7","q": "The perimeter P of a square is related to its side length s by P = 4s. The area A of a square is related to its side length s by A = s². Which relationship is proportional and why?","a": "Only P = 4s is proportional because {P/s} is always 4, whereas {A/s} equals s, which changes.","lvl": 3,"choices": ["Both are proportional because both pass through (0, 0).","Neither is proportional because side length can vary.","Only A = s² is proportional because squaring is a constant operation.","Only P = 4s is proportional because {P/s} is always 4, whereas {A/s} equals s, which changes."]},{"id": "8.7-16","std": "8.7","q": "A table shows (x, y) pairs: (3, 12), (5, 20), and (8, k). If the relationship is proportional, what is k? If the relationship is linear with a y-intercept of 3 instead, what would the y-value be when x = 3 if the slope stayed 4?","a": "k = 32; with a y-intercept of 3, y would be 15.","lvl": 3,"choices": ["k = 23; with a y-intercept of 3, y would be 12.","k = 32; with a y-intercept of 3, y would be 15.","k = 24; with a y-intercept of 3, y would be 15.","k = 32; with a y-intercept of 3, y would be 9."]},{"id": "8.7-17","std": "8.7","q": "Temperature in degrees Celsius (C) and degrees Fahrenheit (F) are related by F = 1.8C + 32. Explain why this linear relationship is not proportional.","a": "When C = 0, F = 32 instead of 0, so the graph does not pass through the origin (0, 0).","lvl": 3,"choices": ["F increases faster than C.","When C = 0, F = 32 instead of 0, so the graph does not pass through the origin (0, 0).","Temperature can be negative, and proportional relationships only use positive numbers.","The slope 1.8 is a decimal rather than a whole number."]},{"id": "8.8-09","std": "8.8","q": "A proportional relationship is modeled by the equation y = 6.5x. What is the slope of the graph of this relationship?","a": "6.5","lvl": 1,"part": "a","choices": ["0","1","6.5","13"]},{"id": "8.8-10","std": "8.8","q": "Every graph of a proportional relationship must pass through which point?","a": "(0, 0)","lvl": 1,"choices": ["(1, 0)","(1, 1)","(0, 1)","(0, 0)"]},{"id": "8.8-11","std": "8.8","q": "The graph of a proportional relationship passes through (0, 0) and (4, 28). What is the unit rate?","a": "7","lvl": 1,"part": "a","choices": ["4","{1/7}","24","7"]},{"id": "8.8-12","std": "8.8","q": "A cyclist rides at a constant speed. The graph of distance in miles (y) versus time in hours (x) passes through the origin and the point (3, 45). Write the equation that represents this relationship and interpret the slope.","a": "y = 15x; the cyclist rides 15 miles per hour.","lvl": 2,"part": "a","choices": ["y = 15x + 3; the cyclist starts 3 miles from home.","y = 45x; the cyclist rides 45 miles per hour.","y = 15x; the cyclist rides 15 miles per hour.","y = {1/15}x; the cyclist takes 15 hours to go 1 mile."]},{"id": "8.8-13","std": "8.8","q": "Line A represents y = 3x and Line B represents y = {5/2}x. If both are graphed on the same coordinate plane, which line is steeper and why?","a": "Line A is steeper because its slope 3 is greater than Line B's slope 2.5.","lvl": 2,"choices": ["Line A is steeper because its slope 3 is greater than Line B's slope 2.5.","Line B is steeper because fractions create steeper slopes.","Line B is steeper because 5 is greater than 3.","Both lines have the same steepness because both pass through (0, 0)."]},{"id": "8.8-14","std": "8.8","q": "A graph showing the cost y of buying x pounds of almonds passes through (0, 0) and (5, 32.50). Which point also lies on this graph?","a": "(2, 13)","lvl": 2,"part": "a","choices": ["(2, 13)","(1, 5.50)","(3, 18.50)","(4, 24)"]},{"id": "8.8-15","std": "8.8","q": "Two water tanks are being filled at constant rates starting from empty. On a graph of gallons (y) versus minutes (x), Tank 1's line passes through (4, 18) and Tank 2's line passes through (6, 30). After 10 minutes, how much more water is in Tank 2 than in Tank 1?","a": "5 gallons","lvl": 3,"part": "a","choices": ["0.5 gallons","5 gallons","12 gallons","45 gallons"]},{"id": "8.8-16","std": "8.8","q": "A proportional graph passes through (0, 0) and (a, b), where a > 0 and b > 0. What are the coordinates of the point on the graph where x = 1?","a": "(1, {b/a})","lvl": 3,"choices": ["(1, {a/b})","(1, b − a)","(1, {b/a})","(1, ab)"]},{"id": "8.8-17","std": "8.8","q": "A recipe uses 2.5 cups of flour for every 4 dozen cookies. If you graph dozens of cookies on the x-axis and cups of flour on the y-axis, what is the slope of the line, and what does the point (10, 6.25) represent?","a": "Slope is 0.625; 10 dozen cookies require 6.25 cups of flour.","lvl": 3,"part": "a","choices": ["Slope is 0.625; 10 dozen cookies require 6.25 cups of flour.","Slope is 2.5; 10 dozen cookies require 6.25 cups of flour.","Slope is 0.625; 6.25 dozen cookies require 10 cups of flour.","Slope is 1.6; 10 cups of flour make 6.25 dozen cookies."]},{"id": "8.9-12","std": "8.9","q": "In the linear equation y = −4x + 9, what are the slope and the y-intercept?","a": "Slope = −4, y-intercept = 9","lvl": 1,"choices": ["Slope = −4, y-intercept = −9","Slope = 9, y-intercept = −4","Slope = 4, y-intercept = 9","Slope = −4, y-intercept = 9"]},{"id": "8.9-13","std": "8.9","q": "Find the slope of the line that passes through the points (2, 5) and (6, 13).","a": "2","lvl": 1,"part": "b","choices": ["8","2","{1/2}","4"]},{"id": "8.9-14","std": "8.9","q": "A taxi charges a §3 initial fee plus §2 per mile. Which equation models the total cost y for x miles?","a": "y = 2x + 3","lvl": 1,"part": "c","choices": ["y = 2x − 3","y = 5x","y = 3x + 2","y = 2x + 3"]},{"id": "8.9-15","std": "8.9","q": "Find the slope of the line passing through (−3, 7) and (3, −5).","a": "−2","lvl": 2,"part": "b","choices": ["{1/3}","−{1/2}","2","−2"]},{"id": "8.9-16","std": "8.9","q": "On a non-vertical line, right triangle ABC is drawn with vertical leg 6 and horizontal leg 4. Another right triangle DEF is drawn on the same line with horizontal leg 10. What is the length of the vertical leg of triangle DEF?","a": "15","lvl": 2,"part": "a","choices": ["6.67","12","15","24"]},{"id": "8.9-17","std": "8.9","q": "Line 1 passes through (0, 2) and (3, 8). Line 2 passes through (0, −4) and (3, 2). How do the graphs of Line 1 and Line 2 compare?","a": "They have the same slope of 2, so they are parallel lines with different y-intercepts.","lvl": 2,"part": "d","choices": ["They have the same slope of 2, so they are parallel lines with different y-intercepts.","They are the exact same line.","They have different slopes but the same y-intercept.","They intersect at (3, 2)."]},{"id": "8.9-18","std": "8.9","q": "Explain how similar right triangles on a coordinate plane prove that the slope of a non-vertical line is constant between any two points.","a": "Any two right triangles formed using segments of the line as hypotenuses and horizontal/vertical legs are similar by AA similarity, so the ratios of rise to run are equal.","lvl": 3,"part": "a","choices": ["The hypotenuses are always the same length on a straight line.","Any two right triangles formed using segments of the line as hypotenuses and horizontal/vertical legs are similar by AA similarity, so the ratios of rise to run are equal.","All right triangles have the same area, so their sides are equal.","The sum of the rise and run is always 180 degrees."]},{"id": "8.9-19","std": "8.9","q": "A candle is 14 inches tall when lit and burns at a steady rate of 1.5 inches per hour. Write the linear equation for its height h after t hours, and find how tall the candle is after 6 hours.","a": "h = −1.5t + 14; 5 inches","lvl": 3,"part": "c","choices": ["h = −1.5t + 14; 9 inches","h = 1.5t + 14; 23 inches","h = −1.5t + 14; 5 inches","h = 14t − 1.5; 82.5 inches"]},{"id": "8.9-20","std": "8.9","q": "Set A contains points (1, 5) and (4, 14). Set B contains points (−2, −10) and (2, 2). Do the lines through Set A and Set B have the same slope? What are their y-intercepts?","a": "Yes, both have slope 3; Set A has y-intercept 2 and Set B has y-intercept −4.","lvl": 3,"part": "d","choices": ["No, Set A has slope 3 and Set B has slope −3.","Yes, both have slope 3 and both have y-intercept 2.","Yes, both have slope 3; Set A has y-intercept 2 and Set B has y-intercept −4.","Yes, both have slope {1/3}; Set A has y-intercept 2 and Set B has y-intercept −4."]},{"id": "8.10-09","std": "8.10","q": "Plan A is modeled by y = 12x. Plan B is modeled by y = 8x + 20. Which plan costs less for x = 3?","a": "Plan A (§36 vs. §44)","lvl": 1,"choices": ["Plan A (§36 vs. §44)","Plan B (§36 vs. §44)","Plan B (§24 vs. §36)","They cost the same (§36)"]},{"id": "8.10-10","std": "8.10","q": "Function 1 is y = 5x + 1. Function 2 is shown in a table: (0, 0), (2, 12), (4, 24). Which function has a greater rate of change?","a": "Function 2 (rate of change is 6)","lvl": 1,"choices": ["Function 2 (rate of change is 6)","They have the same rate of change","Function 1 (rate of change is 5)","Function 2 (rate of change is 12)"]},{"id": "8.10-11","std": "8.10","q": "Which representation shows a proportional relationship?","a": "A line passing through (0, 0) and (3, 15)","lvl": 1,"choices": ["A line passing through (0, 0) and (3, 15)","y = 4x − 1","A table with (1, 5), (2, 8), (3, 11)","A line passing through (0, 2) and (3, 14)"]},{"id": "8.10-12","std": "8.10","q": "Store A sells notebooks for §2.50 each with no membership fee. Store B charges a §10 membership fee and sells notebooks for §1.50 each. For what number of notebooks is the total cost the same at both stores?","a": "10 notebooks","lvl": 2,"choices": ["4 notebooks","5 notebooks","10 notebooks","25 notebooks"]},{"id": "8.10-13","std": "8.10","q": "Runner 1's distance is given by d = 7t (d in meters, t in seconds). Runner 2 starts 12 meters ahead of the starting line and runs at 5 meters per second. Who is farther from the starting line after 8 seconds, and by how much?","a": "Runner 1 is farther by 4 meters.","lvl": 2,"choices": ["They are at the exact same distance.","Runner 1 is farther by 16 meters.","Runner 2 is farther by 4 meters.","Runner 1 is farther by 4 meters."]},{"id": "8.10-14","std": "8.10","q": "Company X's fee is represented by a line through (0, 0) and (4, 100). Company Y's fee is y = 20x + 30. Which company has a lower initial fee, and which has a higher hourly rate?","a": "Company X has the lower initial fee (§0) and the higher hourly rate (§25 per hour).","lvl": 2,"choices": ["Company X has the lower initial fee (§0) and the higher hourly rate (§25 per hour).","Company Y has the lower initial fee and the higher hourly rate.","Company X has both the lower initial fee and the lower hourly rate.","Company Y has the lower initial fee (§30) and the higher hourly rate (§20 per hour)."]},{"id": "8.10-15","std": "8.10","q": "Drone A starts on the ground and climbs at 4 meters per second. Drone B starts on a 15-meter roof and climbs at 2.5 meters per second. After how many seconds will both drones be at the same altitude, and what will that altitude be?","a": "10 seconds, at an altitude of 40 meters","lvl": 3,"choices": ["10 seconds, at an altitude of 40 meters","6 seconds, at an altitude of 24 meters","15 seconds, at an altitude of 60 meters","10 seconds, at an altitude of 25 meters"]},{"id": "8.10-16","std": "8.10","q": "Car Rental 1 is proportional: 3 days cost §135. Car Rental 2 is shown in a table: 2 days cost §110, 4 days cost §180, 6 days cost §250. How much money do you save by choosing the cheaper option for a 5-day rental?","a": "§10","lvl": 3,"choices": ["§5","§10","§15","§25"]},{"id": "8.10-17","std": "8.10","q": "Account 1 starts with §0 and adds §45 per week. Account 2 starts with §180 and adds §30 per week. For which number of weeks w does Account 1 have more money than Account 2?","a": "w > 12","lvl": 3,"choices": ["w > 10","w < 12","w > 4","w > 12"]},{"id": "8.11-17","std": "8.11","q": "Solve for x: 4(x − 3) = 28","a": "x = 10","lvl": 1,"choices": ["x = 4","x = 10","x = 25","x = 7.75"]},{"id": "8.11-18","std": "8.11","q": "Solve for n: 5n − 8 = 2n + 13","a": "n = 7","lvl": 1,"choices": ["n = 21","n = {5/3}","n = 5","n = 7"]},{"id": "8.11-19","std": "8.11","q": "How many solutions does the equation 6x − 1 = 6x + 5 have?","a": "No solution","lvl": 1,"part": "a","choices": ["Infinitely many solutions","Two solutions","One solution","No solution"]},{"id": "8.11-20","std": "8.11","q": "Solve for x: {1/2}(6x − 10) + 4 = 2x + 3","a": "x = 4","lvl": 2,"choices": ["x = 4","x = 8","x = 12","x = 2"]},{"id": "8.11-21","std": "8.11","q": "Determine the number of solutions for the equation: 2(3x − 5) = 6x − 10","a": "Infinitely many solutions","lvl": 2,"part": "a","choices": ["No solution","Infinitely many solutions","One solution (x = 0)","One solution (x = 10)"]},{"id": "8.11-22","std": "8.11","q": "The perimeter of a rectangle is 54 centimeters. The length is 3 centimeters more than twice the width w. Write and solve an equation to find the width of the rectangle.","a": "w = 8 cm","lvl": 2,"part": "b","choices": ["w = 24 cm","w = 17 cm","w = 8 cm","w = 16 cm"]},{"id": "8.11-23","std": "8.11","q": "Find the value of k so that the equation 5(2x − 3) + k = 10x − 8 has infinitely many solutions.","a": "k = 7","lvl": 3,"part": "a","choices": ["k = 23","k = 7","k = −8","k = −5"]},{"id": "8.11-24","std": "8.11","q": "Solve for x: {3/4}x − 5 = {1/2}x + 2","a": "x = 28","lvl": 3,"choices": ["x = 12","x = −12","x = 28","x = {7/4}"]},{"id": "8.11-25","std": "8.11","q": "Three consecutive integers have a sum of 72. If n represents the smallest integer, solve n + (n + 1) + (n + 2) = 72 and identify the largest of the three integers.","a": "25","lvl": 3,"part": "b","choices": ["23","24","25","26"]},{"id": "8.12-12","std": "8.12","q": "Two lines graphed on a coordinate plane intersect at the point (−2, 5). What is the solution to the system of equations represented by the two lines?","a": "(−2, 5)","lvl": 1,"part": "a","choices": ["No solution","x = −2 only","(−2, 5)","(5, −2)"]},{"id": "8.12-13","std": "8.12","q": "Solve the system of equations using substitution: y = 3x and x + y = 20.","a": "(5, 15)","lvl": 1,"choices": ["(5, 15)","(4, 12)","(15, 5)","(6, 18)"]},{"id": "8.12-14","std": "8.12","q": "The graphs of two linear equations are parallel lines that never intersect. How many solutions does the system have?","a": "No solution","lvl": 1,"part": "b","choices": ["One solution","Infinitely many solutions","Two solutions","No solution"]},{"id": "8.12-15","std": "8.12","q": "Solve the system of equations: y = 2x − 3 and y = −x + 9.","a": "(4, 5)","lvl": 2,"choices": ["(4, 5)","(5, 4)","(2, 1)","(12, 21)"]},{"id": "8.12-16","std": "8.12","q": "At a school bake sale, 25 items (cookies and brownies) were sold for a total of §40. Cookies cost §1 each and brownies cost §2 each. Using the system c + b = 25 and c + 2b = 40, how many brownies were sold?","a": "15 brownies","lvl": 2,"part": "b","choices": ["10 brownies","15 brownies","20 brownies","25 brownies"]},{"id": "8.12-17","std": "8.12","q": "Without graphing, determine how many solutions the system y = 4x + 1 and 2y = 8x + 2 has.","a": "Infinitely many solutions","lvl": 2,"part": "b","choices": ["Infinitely many solutions","One solution","Two solutions","No solution"]},{"id": "8.12-18","std": "8.12","q": "Solve the system of equations using substitution: 3x + 2y = 19 and y = 4x − 7.","a": "(3, 5)","lvl": 3,"choices": ["(3, 5)","(2, 1)","(5, 3)","(1, −3)"]},{"id": "8.12-19","std": "8.12","q": "A student says the point (3, 7) is the solution to the system y = 2x + 1 and y = 3x − 3. Is the student correct? Explain why or why not.","a": "No, because (3, 7) satisfies y = 2x + 1, but for y = 3x − 3 when x = 3, y = 6, not 7.","lvl": 3,"part": "a","choices": ["No, because (3, 7) satisfies neither equation.","No, because (3, 7) satisfies y = 2x + 1, but for y = 3x − 3 when x = 3, y = 6, not 7.","Yes, because both lines have positive slopes.","Yes, because 2(3) + 1 = 7."]},{"id": "8.12-20","std": "8.12","q": "For what value of b will the system y = −3x + 4 and 6x + 2y = b have no solution?","a": "Any number except 8","lvl": 3,"part": "b","choices": ["Only b = −3","Only b = 8","Any number except 8","Only b = 4"]},{"id": "8.13-09","std": "8.13","q": "Which set of ordered pairs represents a function?","a": "{(1, 4), (2, 4), (3, 5), (4, 6)}","lvl": 1,"choices": ["{(1, 4), (2, 4), (3, 5), (4, 6)}","{(2, 1), (3, 2), (2, 5), (4, 6)}","{(1, 2), (1, 3), (2, 4), (3, 5)}","{(0, 1), (0, −1), (1, 2), (2, 3)}"]},{"id": "8.13-10","std": "8.13","q": "In a function, each input value is paired with how many output values?","a": "Exactly one output value","lvl": 1,"choices": ["Any number of output values","Zero output values","Exactly one output value","At least two output values"]},{"id": "8.13-11","std": "8.13","q": "A table shows inputs x: 2, 4, 6, 4 and outputs y: 5, 9, 13, 11. Does this table represent a function?","a": "No, because the input 4 has two different outputs (9 and 11).","lvl": 1,"choices": ["No, because the input 4 has two different outputs (9 and 11).","No, because the outputs do not increase steadily.","Yes, because the inputs are all even numbers.","Yes, because every output is different."]},{"id": "8.13-12","std": "8.13","q": "Consider the set of ordered pairs: {(3, 7), (5, 7), (8, 7), (10, 7)}. Is this relation a function? Explain.","a": "Yes, because each input has only one output, even though all inputs share the same output.","lvl": 2,"choices": ["No, because the inputs do not increase by a constant amount.","Yes, because each input has only one output, even though all inputs share the same output.","Yes, because the ordered pairs form a vertical line.","No, because the output 7 is repeated four times."]},{"id": "8.13-13","std": "8.13","q": "Which relation is NOT a function?","a": "x = 5","lvl": 2,"choices": ["y = 2x − 3","x = 5","y = 5","y = x²"]},{"id": "8.13-14","std": "8.13","q": "A relation contains the points (2, 6), (4, 10), (k, 14), and (8, 18). Which value of k would make the relation NOT a function?","a": "4","lvl": 2,"choices": ["0","4","6","10"]},{"id": "8.13-15","std": "8.13","q": "Consider two relations: Relation A pairs each student in a class with their birth month. Relation B pairs each birth month with the students born in that month. Which relation is always a function?","a": "Relation A only, because each student has only one birth month.","lvl": 3,"choices": ["Relation A only, because each student has only one birth month.","Relation B only, because there are only 12 months.","Neither relation is a function.","Both Relation A and Relation B are always functions."]},{"id": "8.13-16","std": "8.13","q": "A circle with radius 5 centered at (0, 0) is graphed on a coordinate plane. Explain why the circle does not represent y as a function of x.","a": "For x = 0, there are two y-values (5 and −5), meaning an input has more than one output.","lvl": 3,"choices": ["A circle has no straight lines.","The radius is 5 instead of 1.","For x = 0, there are two y-values (5 and −5), meaning an input has more than one output.","The circle passes through negative quadrants."]},{"id": "8.13-17","std": "8.13","q": "Given the relation {(−1, 3), (0, 5), (2, 9), (2, 3a − 3)}, what must the value of a be for this relation to be a function?","a": "4","lvl": 3,"choices": ["2","3","4","6"]},{"id": "8.14-09","std": "8.14","q": "Evaluate the function y = 4x − 7 when x = 5.","a": "13","lvl": 1,"choices": ["−2","13","20","27"]},{"id": "8.14-10","std": "8.14","q": "Given the function f(x) = −2x + 10, find f(3).","a": "4","lvl": 1,"choices": ["−4","4","5","16"]},{"id": "8.14-11","std": "8.14","q": "A function rule is: 'Multiply the input by 3, then add 2.' What is the output when the input is −4?","a": "−10","lvl": 1,"choices": ["−14","−10","10","14"]},{"id": "8.14-12","std": "8.14","q": "Evaluate f(x) = {2/3}x − 5 for x = −9.","a": "−11","lvl": 2,"choices": ["−11","−1","1","11"]},{"id": "8.14-13","std": "8.14","q": "The function C(m) = 0.15m + 25 represents the monthly cost in dollars of a phone plan for m text messages. Find C(120) and state what it means.","a": "§43; sending 120 text messages costs §43.","lvl": 2,"choices": ["§18; sending 120 text messages costs §18.","§43; 43 text messages cost §120.","§43; sending 120 text messages costs §43.","§145; sending 120 text messages costs §145."]},{"id": "8.14-14","std": "8.14","q": "For the function g(x) = x² − 4x + 1, what is the value of g(−2)?","a": "13","lvl": 2,"choices": ["−11","−3","5","13"]},{"id": "8.14-15","std": "8.14","q": "If f(x) = 3x − 8 and f(a) = 19, what is the value of a?","a": "9","lvl": 3,"choices": ["−9","49","9","{11/3}"]},{"id": "8.14-16","std": "8.14","q": "Given p(x) = −2x + 7 and q(x) = x² − 3, find the value of p(4) + q(−3).","a": "5","lvl": 3,"choices": ["−13","−7","5","21"]},{"id": "8.14-17","std": "8.14","q": "A tank drains according to V(t) = 120 − 4.5t, where V is gallons remaining after t minutes. How much water has drained out of the tank between t = 4 and t = 12?","a": "36 gallons","lvl": 3,"choices": ["18 gallons","36 gallons","54 gallons","66 gallons"]},{"id": "8.15-09","std": "8.15","q": "Which equation represents a non-linear function?","a": "y = x² + 3","lvl": 1,"part": "a","choices": ["y = x² + 3","y = {1/4}x − 2","y = 2x + 5","y = −x"]},{"id": "8.15-10","std": "8.15","q": "Function A is y = 3x + 4. Function B has a slope of 5 and a y-intercept of 2. Which function has the greater y-intercept?","a": "Function A","lvl": 1,"choices": ["Neither has a y-intercept","Function B","Function A","Both have the same y-intercept"]},{"id": "8.15-11","std": "8.15","q": "What is the shape of the graph of every linear function?","a": "A straight line","lvl": 1,"part": "a","choices": ["A straight line","A circle","A U-shaped curve","A V-shape"]},{"id": "8.15-12","std": "8.15","q": "Examine the table: x = 1, y = 2; x = 2, y = 5; x = 3, y = 10; x = 4, y = 17. Is this function linear or non-linear? Explain.","a": "Non-linear, because the rate of change between consecutive points is not constant (+3, +5, +7).","lvl": 2,"part": "a","choices": ["Non-linear, because the rate of change between consecutive points is not constant (+3, +5, +7).","Non-linear, because the numbers are not multiples of 2.","Linear, because y increases as x increases.","Linear, because x increases by 1 each time."]},{"id": "8.15-13","std": "8.15","q": "Linear Function 1 is y = −2x + 8. Linear Function 2 is shown in a table: (0, 6), (2, 0), (4, −6). Which function has a steeper negative slope?","a": "Linear Function 2 (slope = −3)","lvl": 2,"choices": ["Linear Function 2 (slope = −3)","They have the same slope","Linear Function 2 (slope = −6)","Linear Function 1 (slope = −2)"]},{"id": "8.15-14","std": "8.15","q": "Function P is represented by y = 4x − 3. Function Q is a linear function passing through (1, 3) and (3, 11). Compare their slopes and y-intercepts.","a": "They have the same slope (4), but different y-intercepts (−3 and −1).","lvl": 2,"choices": ["They have the same y-intercept (−3), but different slopes.","They have the same slope (4) and the same y-intercept (−3).","They have the same slope (4), but different y-intercepts (−3 and −1).","They have different slopes (4 and 8), and different y-intercepts."]},{"id": "8.15-15","std": "8.15","q": "A table shows the points (2, 10), (5, 19), and (9, k). What value of k makes this a linear function, and why would any other value of k make it non-linear?","a": "k = 31; a linear function requires a constant rate of change of 3, and 19 + 3(4) = 31.","lvl": 3,"part": "a","choices": ["k = 31; a linear function requires a constant rate of change of 3, and 19 + 3(4) = 31.","k = 34; a linear function increases by 15.","k = 28; a linear function adds 9 each step.","k = 27; 9 times 3 is 27."]},{"id": "8.15-16","std": "8.15","q": "Function A is y = 0.5x + 6. Function B is described verbally: 'Start at 10 and decrease by 1.5 for every unit increase in x.' At what x-value do both functions produce the same output?","a": "x = 2","lvl": 3,"choices": ["x = 4","x = −2","x = 2","x = 8"]},{"id": "8.15-17","std": "8.15","q": "Which of the following formulas represents a linear function of its variable: (1) Circumference of a circle C = 2πr, or (2) Area of a circle A = πr²?","a": "Circumference C = 2πr only, because the variable r is raised to the first power.","lvl": 3,"part": "a","choices": ["Area A = πr² only, because area grows steadily.","Circumference C = 2πr only, because the variable r is raised to the first power.","Both are linear because π is a constant.","Neither is linear because π is irrational."]},{"id": "8.16-10","std": "8.16","q": "A savings account starts with §50 and increases by §20 each week. What is the initial value and rate of change of this linear function?","a": "Initial value = §50, rate of change = §20 per week","lvl": 1,"part": "a","choices": ["Initial value = §20, rate of change = §50 per week","Initial value = §50, rate of change = §20 per week","Initial value = §0, rate of change = §50 per week","Initial value = §70, rate of change = §20 per week"]},{"id": "8.16-11","std": "8.16","q": "Write a linear function y = mx + b for a line with a rate of change of 4 and an initial value of −6.","a": "y = 4x − 6","lvl": 1,"choices": ["y = −6x + 4","y = 4x + 6","y = 4x − 6","y = −4x − 6"]},{"id": "8.16-12","std": "8.16","q": "A table of a linear function contains the points (0, 12) and (3, 27). What is the rate of change?","a": "5","lvl": 1,"part": "a","choices": ["5","9","12","15"]},{"id": "8.16-13","std": "8.16","q": "A linear function passes through the points (2, 11) and (5, 23). Write the equation of the function in y = mx + b form.","a": "y = 4x + 3","lvl": 2,"choices": ["y = 4x + 3","y = 4x + 11","y = 3x + 5","y = {1/4}x + 10.5"]},{"id": "8.16-14","std": "8.16","q": "A pool is being drained at a constant rate. After 2 hours, there are 8,500 gallons left. After 6 hours, there are 5,500 gallons left. Find and interpret the rate of change.","a": "−750 gallons per hour; the pool loses 750 gallons of water each hour.","lvl": 2,"part": "a","choices": ["−3,000 gallons per hour; the pool loses 3,000 gallons each hour.","−750 gallons per hour; the pool loses 750 gallons of water each hour.","−500 gallons per hour; the pool loses 500 gallons each hour.","750 gallons per hour; the pool gains 750 gallons each hour."]},{"id": "8.16-15","std": "8.16","q": "A banquet hall charges a flat rental fee plus a fixed price per guest. For 20 guests, the total cost is §750. For 50 guests, the total cost is §1,500. Construct the linear function C(g) for g guests.","a": "C(g) = 25g + 250","lvl": 2,"choices": ["C(g) = 37.5g","C(g) = 30g + 150","C(g) = 25g + 250","C(g) = 25g + 750"]},{"id": "8.16-16","std": "8.16","q": "In the banquet hall problem where C(g) = 25g + 250, what do the numbers 25 and 250 represent in the context of the problem?","a": "§25 is the cost per guest, and §250 is the flat rental fee when there are 0 guests.","lvl": 3,"part": "a","choices": ["§25 is the cost per guest, and §250 is the flat rental fee when there are 0 guests.","§250 is the cost per guest, and §25 is the flat rental fee.","§25 is the discount per guest, and §250 is the deposit.","§25 is the minimum number of guests, and §250 is the maximum cost."]},{"id": "8.16-17","std": "8.16","q": "An airplane descends at a steady rate. At 4 minutes into its descent, its altitude is 26,000 feet. At 10 minutes, its altitude is 17,000 feet. How many minutes after starting its descent will the airplane land (altitude = 0 feet)?","a": "21{1/3} minutes","lvl": 3,"choices": ["15 minutes","17{1/3} minutes","21{1/3} minutes","25 minutes"]},{"id": "8.16-18","std": "8.16","q": "A table of a linear function gives (−3, 14) and (6, −4). What is the initial value (y-intercept) of this function?","a": "8","lvl": 3,"choices": ["−2","2","8","20"]},{"id": "8.17-09","std": "8.17","q": "On a graph, a line goes downward from left to right. How is this function described?","a": "Decreasing and linear","lvl": 1,"choices": ["Increasing and non-linear","Decreasing and non-linear","Decreasing and linear","Increasing and linear"]},{"id": "8.17-10","std": "8.17","q": "A graph shows a horizontal flat line segment from x = 2 to x = 5 at y = 10. What is happening to y during this interval?","a": "y remains constant (neither increasing nor decreasing).","lvl": 1,"choices": ["y remains constant (neither increasing nor decreasing).","y is decreasing rapidly.","y is increasing rapidly.","y is equal to zero."]},{"id": "8.17-11","std": "8.17","q": "A U-shaped curve opens upward on a graph, falling from x = −3 to x = 0 and rising from x = 0 to x = 3. Is this function linear or non-linear?","a": "Non-linear","lvl": 1,"choices": ["Constant","Linear","Non-linear","Undefined"]},{"id": "8.17-12","std": "8.17","q": "Maria walks from her house to the library, stays there to read for 30 minutes, and then runs home faster than she walked. On a distance-from-home vs. time graph, which section has the steepest slope?","a": "The final section when she runs home","lvl": 2,"choices": ["All three sections have the same slope","The first section when she walks to the library","The final section when she runs home","The middle section while she reads at the library"]},{"id": "8.17-13","std": "8.17","q": "A graph of a function is broken into three linear intervals: Interval 1 goes from (0, 2) to (3, 8); Interval 2 goes from (3, 8) to (6, 8); Interval 3 goes from (6, 8) to (8, 0). During which interval is the function increasing?","a": "Interval 1 (0 < x < 3)","lvl": 2,"choices": ["Interval 2 (3 < x < 6)","Interval 3 (6 < x < 8)","Intervals 1 and 3","Interval 1 (0 < x < 3)"]},{"id": "8.17-14","std": "8.17","q": "A ball is thrown straight up into the air and falls back to the ground. Which description best matches the graph of the ball's height over time?","a": "Non-linear; it increases at a slowing rate to a peak, then decreases at a faster rate.","lvl": 2,"choices": ["Linear; it stays horizontal at its maximum height.","Non-linear; it increases at a slowing rate to a peak, then decreases at a faster rate.","Linear; it increases steadily to a sharp point and decreases linearly.","Non-linear; it decreases from start to finish."]},{"id": "8.17-15","std": "8.17","q": "Compare two intervals of a piecewise linear graph: Interval A connects (1, 4) to (4, 13), and Interval B connects (4, 13) to (6, 3). Which interval has a greater rate of change in magnitude (steepness), and is it increasing or decreasing?","a": "Interval B is steeper (rate of change −5 vs. +3) and is decreasing.","lvl": 3,"choices": ["Interval A is steeper (rate of change +3 vs. −5) and is increasing.","Both intervals have the exact same steepness.","Interval A is steeper (rate of change +9 vs. −10) and is increasing.","Interval B is steeper (rate of change −5 vs. +3) and is decreasing."]},{"id": "8.17-16","std": "8.17","q": "Water is poured at a constant rate into a vase that is wide at the bottom and narrow at the top. Describe the graph of water height (y) versus time (x).","a": "Increasing and non-linear; the graph gets steeper as time increases because the narrow top fills faster.","lvl": 3,"choices": ["Increasing and linear because water is poured at a constant rate.","Decreasing and non-linear.","Increasing and non-linear; the graph gets steeper as time increases because the narrow top fills faster.","Increasing and non-linear; the graph gets flatter as time increases."]},{"id": "8.17-17","std": "8.17","q": "A population of bacteria doubles every hour. Sketching population versus hours produces a curve that rises slowly at first and then shoots upward sharply. How would you classify this relationship?","a": "Increasing and non-linear","lvl": 3,"choices": ["Increasing and non-linear","Decreasing and non-linear","Increasing and linear","Constant and linear"]},{"id": "8.18-09","std": "8.18","q": "In a scatter plot, as the x-values increase, the y-values generally decrease. What type of association does this show?","a": "Negative association","lvl": 1,"choices": ["No association","Positive association","Constant association","Negative association"]},{"id": "8.18-10","std": "8.18","q": "A scatter plot compares students' shoe sizes (x) and their test scores (y). The points are scattered randomly all over the graph with no pattern. What type of association is shown?","a": "No association","lvl": 1,"choices": ["Negative linear association","Non-linear association","No association","Positive linear association"]},{"id": "8.18-11","std": "8.18","q": "On a scatter plot where most points closely follow a straight line, one single point is located very far away from all the others. What is this point called?","a": "An outlier","lvl": 1,"choices": ["A cluster","The y-intercept","An outlier","The origin"]},{"id": "8.18-12","std": "8.18","q": "A scatter plot compares hours spent practicing free throws (x) and number of missed shots out of 50 (y). Which pattern would you expect to see?","a": "Negative linear association","lvl": 2,"choices": ["Positive linear association","No association","Negative linear association","Circular clustering"]},{"id": "8.18-13","std": "8.18","q": "A scatter plot of daily outdoor temperature vs. ice cream sales shows points tightly grouped along an upward-sloping line, except for one point at (95 degrees, 5 sales). What does that outlier most likely represent?","a": "A very hot day when the ice cream shop had a power outage or closed early","lvl": 2,"choices": ["Proof that there is no association between temperature and sales","A cold winter day with high sales","A normal hot summer day","A very hot day when the ice cream shop had a power outage or closed early"]},{"id": "8.18-14","std": "8.18","q": "In a scatter plot, the points form a clear U-shaped curve rather than a straight line. How should this pattern be described?","a": "Non-linear association","lvl": 2,"choices": ["Positive linear association","Non-linear association","Negative linear association","No association"]},{"id": "8.18-15","std": "8.18","q": "A scatter plot of car age in years (x) versus resale value in dollars (y) shows two distinct clusters: one cluster around 1 to 3 years old (§22,000–§28,000) and another cluster around 10 to 12 years old (§5,000–§8,000). Overall, what is the association, and what do the clusters tell you?","a": "Negative association; the dataset mainly contains newer cars and older cars, with few mid-aged cars.","lvl": 3,"choices": ["Positive association; older cars are worth more.","Non-linear association; car values go up and down randomly.","No association; clustering means the variables are unrelated.","Negative association; the dataset mainly contains newer cars and older cars, with few mid-aged cars."]},{"id": "8.18-16","std": "8.18","q": "Which pair of variables would most likely show a strong negative linear association on a scatter plot?","a": "Distance driven on a road trip and gallons of gas remaining in the tank","lvl": 3,"choices": ["Height and age of children from ages 2 to 15","House number and number of pets in the house","Minutes spent studying and test score","Distance driven on a road trip and gallons of gas remaining in the tank"]},{"id": "8.18-17","std": "8.18","q": "A student sees a scatter plot where points slope steeply downward from (1, 95) to (10, 10) very tightly along a line, and says, 'This has a weak association because the slope is negative.' Evaluate the student's statement.","a": "The student is incorrect; the association is strong because the points are tightly clustered near the line, even though the direction is negative.","lvl": 3,"choices": ["The student is incorrect; a downward slope means a positive association.","The student is incorrect; the association is strong because the points are tightly clustered near the line, even though the direction is negative.","The student is correct; only upward lines have strong associations.","The student is correct; negative slopes always mean weak associations."]},{"id": "8.19-09","std": "8.19","q": "What is the main goal when drawing an informal line of best fit on a scatter plot?","a": "To pass through the center of the data with roughly half the points above and half below the line","lvl": 1,"choices": ["To pass through as many points on the axes as possible","To place all data points above the line","To pass through the center of the data with roughly half the points above and half below the line","To connect the first point to the last point"]},{"id": "8.19-10","std": "8.19","q": "A scatter plot shows points that are very close to the line of best fit. What does this indicate about the linear model?","a": "The linear line is a strong fit for the data.","lvl": 1,"choices": ["The slope of the line must be 1.","The linear line is a poor fit for the data.","The linear line is a strong fit for the data.","There is no association between the variables."]},{"id": "8.19-11","std": "8.19","q": "Should a line of best fit always be forced to pass through the origin (0, 0)?","a": "No, only if the data trend naturally passes through (0, 0)","lvl": 1,"choices": ["Yes, every line of best fit must start at (0, 0).","No, only if the data trend naturally passes through (0, 0)","No, a line of best fit can never pass through (0, 0).","Yes, unless the slope is negative."]},{"id": "8.19-12","std": "8.19","q": "A scatter plot has data points at (1, 3), (2, 5), (3, 6), (4, 9), (5, 11), and (6, 12). Which equation is the best line of fit for these data?","a": "y = 2x + 0.5","lvl": 2,"choices": ["y = 5x","y = 0.5x + 6","y = −2x + 12","y = 2x + 0.5"]},{"id": "8.19-13","std": "8.19","q": "Two students draw lines of best fit for the same scatter plot. Student A's line has 5 points above it and 5 points below it, all within 1 unit of the line. Student B's line has 9 points above it and 1 point below it. Whose line is a better fit and why?","a": "Student A's line, because it balances the points evenly above and below and stays close to the data.","lvl": 2,"choices": ["Student B's line, because almost all points are on one side.","Both lines are equally good fits.","Student A's line, because it balances the points evenly above and below and stays close to the data.","Student B's line, because it avoids the middle of the data."]},{"id": "8.19-14","std": "8.19","q": "A scatter plot shows a strong positive linear trend, except for one extreme outlier far below the trend. How should you treat this outlier when drawing an informal line of best fit?","a": "Follow the main cluster of points and do not pull the line sharply down toward the single outlier.","lvl": 2,"choices": ["Ignore all points except the outlier.","Follow the main cluster of points and do not pull the line sharply down toward the single outlier.","Make sure the line passes directly through the outlier.","Draw a vertical line through the outlier."]},{"id": "8.19-15","std": "8.19","q": "A data set has points (2, 18), (4, 15), (6, 11), (8, 9), (10, 5). Which candidate equation best fits this data set: y = −1.6x + 21 or y = −1.6x + 12?","a": "y = −1.6x + 21","lvl": 3,"choices": ["y = −1.6x + 21","Neither, because the slope must be positive","Both fit equally well","y = −1.6x + 12"]},{"id": "8.19-16","std": "8.19","q": "Scatter Plot 1 has points scattered up to 15 units away from its line of best fit. Scatter Plot 2 has points all within 0.5 units of its line of best fit (using the same scale). Which plot will give more reliable predictions and why?","a": "Scatter Plot 2, because the points are much closer to the line, indicating a tighter linear fit.","lvl": 3,"choices": ["Scatter Plot 1, because the points cover a wider area.","Scatter Plot 2, because the points are much closer to the line, indicating a tighter linear fit.","Scatter Plot 1, because larger numbers mean higher accuracy.","Both give equally reliable predictions."]},{"id": "8.19-17","std": "8.19","q": "A scatter plot shows points (1, 10), (2, 14), (3, 19), (4, 22), (5, 27). A student draws a line passing through (1, 10) and (5, 27). Find the slope of the student's line and check whether the middle point (3, 19) lies above, below, or on the line.","a": "Slope = 4.25; the point (3, 19) lies slightly above the line (since y = 18.5 at x = 3).","lvl": 3,"choices": ["Slope = 4; the point (3, 19) lies directly on the line.","Slope = 4.25; the point (3, 19) lies slightly above the line (since y = 18.5 at x = 3).","Slope = 4.25; the point (3, 19) lies slightly below the line.","Slope = 5; the point (3, 19) lies below the line."]},{"id": "8.20-09","std": "8.20","q": "The linear model y = 3.5x + 12 predicts the height in centimeters of a plant after x weeks. What is the predicted height after 6 weeks?","a": "33 cm","lvl": 1,"choices": ["21 cm","33 cm","45.5 cm","75.5 cm"]},{"id": "8.20-10","std": "8.20","q": "In the model y = 8.5x + 40, y is a student's test score and x is hours spent studying. What does the y-intercept 40 represent?","a": "The predicted test score for a student who studies 0 hours","lvl": 1,"part": "a","choices": ["The number of points gained per hour of study","The number of hours needed to pass","The predicted test score for a student who studies 0 hours","The maximum possible score on the test"]},{"id": "8.20-11","std": "8.20","q": "In the linear model y = −2.5x + 80, y is the battery percentage remaining on a phone after x hours of video streaming. What does the slope −2.5 represent?","a": "The battery percentage decreases by 2.5% for each hour of streaming.","lvl": 1,"part": "a","choices": ["The battery percentage decreases by 2.5% for each hour of streaming.","The phone starts at 2.5% battery.","The battery lasts 2.5 hours total.","The battery percentage increases by 2.5% each hour."]},{"id": "8.20-12","std": "8.20","q": "A linear model for the cost y (in dollars) of printing x custom T-shirts is y = 7.5x + 45. If a club has a budget of §270, how many T-shirts can they order according to the model?","a": "30 T-shirts","lvl": 2,"choices": ["24 T-shirts","30 T-shirts","36 T-shirts","42 T-shirts"]},{"id": "8.20-13","std": "8.20","q": "The equation y = 0.75x + 15 models the total weight y (in pounds) of a backpack containing x books. Interpret both the slope and the y-intercept in context.","a": "The empty backpack weighs 15 pounds, and each book adds 0.75 pounds.","lvl": 2,"part": "a","choices": ["The total weight increases by 15 pounds for every 0.75 books.","Each book weighs 15 pounds, and the empty backpack weighs 0.75 pounds.","The empty backpack weighs 15 pounds, and each book adds 0.75 pounds.","The backpack can hold 15 books weighing 0.75 pounds total."]},{"id": "8.20-14","std": "8.20","q": "A bakery's daily profit y (in dollars) from selling x cakes is modeled by y = 14x − 112. How many cakes must the bakery sell to break even (profit = §0)?","a": "8 cakes","lvl": 2,"choices": ["6 cakes","8 cakes","14 cakes","98 cakes"]},{"id": "8.20-15","std": "8.20","q": "A linear model for the temperature y (in degrees Fahrenheit) at an altitude of x thousand feet is y = −3.5x + 74. According to the model, at what altitude will the temperature reach 32 degrees Fahrenheit?","a": "12,000 feet","lvl": 3,"choices": ["12 feet","1,200 feet","12,000 feet","30,285 feet"]},{"id": "8.20-16","std": "8.20","q": "A car's value is modeled by y = −1,800x + 24,000, where x is the car's age in years and y is its value in dollars. Why does this linear model stop making sense in the real world after x = 14 years?","a": "At x = 14, the model predicts y = -§1,200, and a car's value cannot be negative.","lvl": 3,"part": "a","choices": ["At x = 14, the model predicts y = -§1,200, and a car's value cannot be negative.","Cars cannot be driven for more than 14 years.","At x = 14, the y-intercept changes to 0.","At x = 14, the slope becomes positive."]},{"id": "8.20-17","std": "8.20","q": "A scatter plot of weekly advertising spending x (in hundreds of dollars) vs. weekly sales y (in thousands of dollars) is modeled by y = 2.4x + 18. If a store increases its weekly advertising spending by §300, by how much are weekly sales predicted to increase?","a": "§7,200","lvl": 3,"choices": ["§720","§2,400","§7,200","§25,200"]},{"id": "8.21-09","std": "8.21","q": "In a two-way table of 80 students, 32 play a sport and 48 do not. What is the relative frequency of students who play a sport?","a": "0.40 (or 40%)","lvl": 1,"choices": ["0.32 (or 32%)","0.40 (or 40%)","0.60 (or 60%)","0.67 (or 67%)"]},{"id": "8.21-10","std": "8.21","q": "A survey of 50 students asks whether they prefer dogs or cats. Among 30 8th graders, 18 prefer dogs and 12 prefer cats. Among 20 7th graders, 10 prefer dogs and 10 prefer cats. How many total students prefer dogs?","a": "28","lvl": 1,"choices": ["18","22","28","30"]},{"id": "8.21-11","std": "8.21","q": "In a two-way table, a row has 15 students who ride the bus and 10 students who walk, for a row total of 25. What is the row relative frequency of students who walk?","a": "0.40","lvl": 1,"choices": ["0.10","0.25","0.40","0.60"]},{"id": "8.21-12","std": "8.21","q": "A two-way table shows pet ownership and allergy status for 100 people: Have Pet & Allergy = 12; Have Pet & No Allergy = 48; No Pet & Allergy = 18; No Pet & No Allergy = 22. What percentage of people who have a pet also have an allergy?","a": "20%","lvl": 2,"choices": ["12%","20%","30%","40%"]},{"id": "8.21-13","std": "8.21","q": "In a survey of 60 students about video games and homework completion: Plays Games daily: 24 completed homework, 16 did not. Does not play daily: 18 completed homework, 2 did not. Based on row relative frequencies, is there an association between daily gaming and homework completion?","a": "Yes; 90% of non-daily gamers completed homework compared to only 60% of daily gamers.","lvl": 2,"choices": ["Yes; 90% of non-daily gamers completed homework compared to only 60% of daily gamers.","Yes; 40% of non-daily gamers completed homework.","No; both groups had 40 students.","No; more daily gamers completed homework (24 vs. 18)."]},{"id": "8.21-14","std": "8.21","q": "Complete the missing value in this two-way table: Row 1 (Boys): Soccer = 14, Track = ?, Total = 30. Row 2 (Girls): Soccer = 18, Track = 12, Total = 30. What is the column relative frequency of Boys among all Soccer players?","a": "43.75% ({14/32})","lvl": 2,"choices": ["14% ({14/100})","43.75% ({14/32})","46.7% ({14/30})","56.25% ({18/32})"]},{"id": "8.21-15","std": "8.21","q": "A cafeteria surveys 120 students on grade level and lunch choice. 7th Grade: 30 Pizza, 20 Salad (Total 50). 8th Grade: 42 Pizza, 28 Salad (Total 70). Does the data show an association between grade level and lunch choice? Justify using relative frequencies.","a": "No association; 60% of 7th graders and 60% of 8th graders chose pizza.","lvl": 3,"choices": ["Yes, because 42 8th graders chose pizza compared to 30 7th graders.","Yes, because there are 20 more 8th graders than 7th graders.","No association; 50% of each grade chose salad.","No association; 60% of 7th graders and 60% of 8th graders chose pizza."]},{"id": "8.21-16","std": "8.21","q": "In a study of 200 adults, 80 drink coffee daily and 120 do not. Of the coffee drinkers, 75% sleep at least 7 hours. Of the non-coffee drinkers, 50% sleep at least 7 hours. How many total adults in the study sleep at least 7 hours?","a": "120 adults","lvl": 3,"choices": ["60 adults","100 adults","120 adults","125 adults"]},{"id": "8.21-17","std": "8.21","q": "A two-way table compares wearing a helmet and head injury status for 150 cyclists: Helmet (100 total): 5 injured, 95 uninjured. No Helmet (50 total): 20 injured, 30 uninjured. Compare the relative frequency of injury for both groups.","a": "5% of helmet wearers were injured compared to 40% of non-helmet wearers, showing a strong association.","lvl": 3,"choices": ["There is no association because most cyclists in both groups were uninjured.","5% of helmet wearers were injured compared to 40% of non-helmet wearers, showing a strong association.","5% of helmet wearers were injured compared to 20% of non-helmet wearers.","20% of helmet wearers were injured compared to 80% of non-helmet wearers."]},{"id": "8.22-09","std": "8.22","q": "Triangle ABC has side lengths 5 cm, 7 cm, and 9 cm. If Triangle ABC is rotated 90 degrees clockwise, what are the side lengths of the image Triangle A'B'C'?","a": "5 cm, 7 cm, and 9 cm","lvl": 1,"choices": ["2.5 cm, 3.5 cm, and 4.5 cm","5 cm, 7 cm, and 9 cm","10 cm, 14 cm, and 18 cm","90 cm, 90 cm, and 90 cm"]},{"id": "8.22-10","std": "8.22","q": "Angle M measures 68 degrees. After a reflection across a vertical line, what is the measure of the image angle M'?","a": "68 degrees","lvl": 1,"choices": ["22 degrees","68 degrees","112 degrees","136 degrees"]},{"id": "8.22-11","std": "8.22","q": "Which of the following is NOT a rigid motion?","a": "Dilation","lvl": 1,"choices": ["Dilation","Reflection","Rotation","Translation"]},{"id": "8.22-12","std": "8.22","q": "Parallel lines m and n are 4 units apart. Both lines are translated 6 units to the right and 3 units down. Which statement is true about their images m' and n'?","a": "Lines m' and n' are still parallel and remain 4 units apart.","lvl": 2,"choices": ["Lines m' and n' are perpendicular.","Lines m' and n' are still parallel, but are now 10 units apart.","Lines m' and n' are still parallel and remain 4 units apart.","Lines m' and n' intersect at one point."]},{"id": "8.22-13","std": "8.22","q": "Rectangle PQRS is congruent to Rectangle WXYZ. Which sequence of rigid motions could map PQRS onto WXYZ?","a": "A reflection across the y-axis followed by a translation 4 units up","lvl": 2,"part": "a","choices": ["A dilation by a scale factor of 2 followed by a translation","A dilation by a scale factor of {1/2}","A stretch horizontally by 3 units","A reflection across the y-axis followed by a translation 4 units up"]},{"id": "8.22-14","std": "8.22","q": "Quadrilateral ABCD has angle A = 80 degrees, angle B = 100 degrees, angle C = 95 degrees, and angle D = 85 degrees. It undergoes a translation, then a reflection, then a 180-degree rotation to form A'B'C'D'. What is the measure of angle C'?","a": "95 degrees","lvl": 2,"choices": ["80 degrees","85 degrees","95 degrees","100 degrees"]},{"id": "8.22-15","std": "8.22","q": "Triangle JKL has vertices J(1, 2), K(4, 2), and L(1, 6). Triangle J'K'L' has vertices J'(−1, −4), K'(−4, −4), and L'(−1, −8). Describe a two-step sequence of rigid motions that maps JKL onto J'K'L', proving they are congruent.","a": "Rotate 180 degrees about the origin, then translate 2 units down.","lvl": 3,"part": "a","choices": ["Translate 2 units left, then reflect across the x-axis.","Reflect across the x-axis, then translate 2 units down.","Reflect across the y-axis, then translate 6 units down.","Rotate 180 degrees about the origin, then translate 2 units down."]},{"id": "8.22-16","std": "8.22","q": "Figure 1 has an area of 24 square units and a perimeter of 22 units. Figure 2 has an area of 24 square units and a perimeter of 20 units. Can a sequence of rigid motions map Figure 1 onto Figure 2? Explain.","a": "No, because rigid motions preserve all side lengths and perimeters, so congruent figures must have equal perimeters.","lvl": 3,"part": "a","choices": ["Yes, by rotating Figure 1 by 90 degrees.","No, because rigid motions preserve all side lengths and perimeters, so congruent figures must have equal perimeters.","No, because rigid motions change the area of a figure.","Yes, because both figures have the exact same area of 24 square units."]},{"id": "8.22-17","std": "8.22","q": "Line segment AB has endpoints A(2, 3) and B(2, 8). It is reflected across the line y = x, and then rotated 90 degrees counterclockwise about the origin. What is the length of the final image segment A''B''?","a": "5 units","lvl": 3,"choices": ["2 units","5 units","8 units","10 units"]},{"id": "8.23-11","std": "8.23","q": "Point A(3, −5) is translated 4 units left and 2 units up. What are the coordinates of A'?","a": "(−1, −3)","lvl": 1,"choices": ["(7, −7)","(7, −3)","(−1, −7)","(−1, −3)"]},{"id": "8.23-12","std": "8.23","q": "Point B(−4, 6) is reflected across the x-axis. What are the coordinates of B'?","a": "(−4, −6)","lvl": 1,"choices": ["(6, −4)","(−4, −6)","(4, 6)","(4, −6)"]},{"id": "8.23-13","std": "8.23","q": "Point C(2, −3) is dilated with a scale factor of 4 centered at the origin. What are the coordinates of C'?","a": "(8, −12)","lvl": 1,"choices": ["(6, 1)","(0.5, −0.75)","(−8, 12)","(8, −12)"]},{"id": "8.23-14","std": "8.23","q": "Triangle PQR has vertex P(5, −2). If the triangle is rotated 90 degrees counterclockwise about the origin, what are the coordinates of P'?","a": "(2, 5)","lvl": 2,"choices": ["(−2, −5)","(−5, −2)","(2, 5)","(−5, 2)"]},{"id": "8.23-15","std": "8.23","q": "Which coordinate rule represents a reflection across the y-axis?","a": "(x, y) → (−x, y)","lvl": 2,"choices": ["(x, y) → (x, −y)","(x, y) → (−x, y)","(x, y) → (−x, −y)","(x, y) → (y, x)"]},{"id": "8.23-16","std": "8.23","q": "Point M(−6, 9) is dilated by a scale factor of {1/3} centered at the origin, and then translated 2 units right. What are the final coordinates of M''?","a": "(0, 3)","lvl": 2,"choices": ["(0, 5)","(−2, 3)","(0, 3)","(−4, 3)"]},{"id": "8.23-17","std": "8.23","q": "Vertex K(4, 1) undergoes a 180-degree rotation about the origin, followed by a reflection across the x-axis. What single transformation produces the exact same final coordinates?","a": "Reflection across the y-axis","lvl": 3,"choices": ["Translation 8 units left","Rotation 90 degrees clockwise about the origin","Reflection across the y-axis","Reflection across the x-axis"]},{"id": "8.23-18","std": "8.23","q": "A rectangle has vertices at (2, 2), (6, 2), (6, 4), and (2, 4). It is dilated centered at the origin by a scale factor of 2.5. What is the area of the dilated rectangle?","a": "50 square units","lvl": 3,"choices": ["8 square units","20 square units","50 square units","100 square units"]},{"id": "8.23-19","std": "8.23","q": "Point T(x, y) is mapped to T'(−y, x). Which transformation was applied to Point T?","a": "Rotation 90 degrees counterclockwise about the origin","lvl": 3,"choices": ["Rotation 90 degrees counterclockwise about the origin","Rotation 90 degrees clockwise about the origin","Rotation 180 degrees about the origin","Reflection across the line y = −x"]},{"id": "8.24-09","std": "8.24","q": "Triangle A is dilated by a scale factor of 3 and then translated 5 units right to form Triangle B. Are Triangle A and Triangle B similar?","a": "Yes, because a dilation followed by a rigid motion produces similar figures.","lvl": 1,"choices": ["No, because the side lengths changed.","Yes, because they are the exact same size.","No, because translations destroy similarity.","Yes, because a dilation followed by a rigid motion produces similar figures."]},{"id": "8.24-10","std": "8.24","q": "Two rectangles are similar. The smaller rectangle is 3 cm by 5 cm. The larger rectangle has a width of 12 cm. What is the length of the larger rectangle?","a": "20 cm","lvl": 1,"choices": ["14 cm","15 cm","20 cm","60 cm"]},{"id": "8.24-11","std": "8.24","q": "If two triangles are similar, what is true about their corresponding angles?","a": "They are congruent (equal in measure).","lvl": 1,"choices": ["They are multiplied by the scale factor.","They add up to 90 degrees.","They are congruent (equal in measure).","They are supplementary."]},{"id": "8.24-12","std": "8.24","q": "Triangle ABC has vertices A(0, 0), B(4, 0), and C(0, 2). Triangle DEF has vertices D(0, 0), E(−8, 0), and F(0, 4). Which sequence maps ABC onto DEF?","a": "A dilation centered at the origin with scale factor 2, followed by a reflection across the y-axis","lvl": 2,"choices": ["A dilation centered at the origin with scale factor {1/2}, followed by a rotation of 180 degrees","A translation 8 units left followed by a dilation of 2","A dilation centered at the origin with scale factor 2, followed by a reflection across the y-axis","A dilation centered at the origin with scale factor 2, followed by a reflection across the x-axis"]},{"id": "8.24-13","std": "8.24","q": "Rectangle 1 measures 4 inches by 6 inches. Rectangle 2 measures 6 inches by 9 inches. Rectangle 3 measures 6 inches by 8 inches. Which two rectangles are similar?","a": "Rectangle 1 and Rectangle 2","lvl": 2,"choices": ["Rectangle 2 and Rectangle 3","Rectangle 1 and Rectangle 3","Rectangle 1 and Rectangle 2","All three rectangles are similar"]},{"id": "8.24-14","std": "8.24","q": "Circle P has center (2, 3) and radius 4. Circle Q has center (−3, 1) and radius 12. Describe a sequence of transformations that maps Circle P onto Circle Q.","a": "Translate 5 units left and 2 units down, then dilate about (−3, 1) by a scale factor of 3.","lvl": 2,"choices": ["Rotate 180 degrees, then dilate by a scale factor of {1/3}.","Dilate by a scale factor of 8, then translate 5 units left.","Translate 5 units left and 2 units down, then dilate about (−3, 1) by a scale factor of 3.","Translate 5 units right and 2 units up, then dilate by a scale factor of 3."]},{"id": "8.24-15","std": "8.24","q": "Triangle XYZ has vertices X(2, 4), Y(6, 4), and Z(2, 8). Triangle X'Y'Z' has vertices X'(3, −2), Y'(5, −2), and Z'(3, −4). Describe a transformation sequence showing that XYZ is similar to X'Y'Z'.","a": "Dilate about the origin by a scale factor of {1/2}, reflect across the x-axis, and translate 2 units right.","lvl": 3,"choices": ["Dilate about the origin by a scale factor of {1/2}, reflect across the x-axis, and translate 2 units right.","Dilate about the origin by a scale factor of 2, then translate 1 unit right.","Translate 1 unit right and 6 units down, then dilate by {1/2}.","Reflect across the y-axis, then dilate by a scale factor of {1/2}."]},{"id": "8.24-16","std": "8.24","q": "A student argues that any two right triangles are similar because both contain a 90-degree angle. Is the student correct? Give a counterexample or explanation.","a": "Incorrect; a 45-45-90 triangle and a 30-60-90 triangle are both right triangles, but their side ratios and other angles are not equal.","lvl": 3,"choices": ["Incorrect; a 45-45-90 triangle and a 30-60-90 triangle are both right triangles, but their side ratios and other angles are not equal.","Correct; all right triangles can be mapped onto each other with a dilation.","Incorrect; right triangles cannot be dilated.","Correct; having one equal angle guarantees similarity."]},{"id": "8.24-17","std": "8.24","q": "Square A has area 16 square units. Square B has area 100 square units. What is the scale factor of the dilation that maps Square A onto Square B?","a": "2.5","lvl": 3,"choices": ["2.5","4","6.25","84"]},{"id": "8.25-20","std": "8.25","q": "Two parallel lines are cut by a transversal. One of the acute angles formed measures 52 degrees. What is the measure of any obtuse angle formed by these lines?","a": "128 degrees","lvl": 1,"choices": ["38 degrees","52 degrees","128 degrees","180 degrees"]},{"id": "8.25-21","std": "8.25","q": "Parallel lines p and q are cut by a transversal t. Angle 1 and Angle 5 are corresponding angles. If Angle 1 measures 115 degrees, what is the measure of Angle 5?","a": "115 degrees","lvl": 1,"choices": ["25 degrees","65 degrees","115 degrees","180 degrees"]},{"id": "8.25-22","std": "8.25","q": "When two parallel lines are cut by a transversal, what is the relationship between alternate interior angles?","a": "They are congruent (equal in measure).","lvl": 1,"choices": ["They are supplementary.","They add up to 360 degrees.","They are complementary.","They are congruent (equal in measure)."]},{"id": "8.25-23","std": "8.25","q": "Parallel lines m and n are cut by a transversal. Two alternate exterior angles measure (3x + 15) degrees and (5x − 25) degrees. Solve for x.","a": "x = 20","lvl": 2,"choices": ["x = 12.5","x = 20","x = 23.75","x = 5"]},{"id": "8.25-24","std": "8.25","q": "Parallel lines r and s are cut by a transversal. Two same-side (consecutive) interior angles measure (4x + 10) degrees and (2x + 20) degrees. Find the measure of the smaller angle.","a": "70 degrees","lvl": 2,"choices": ["25 degrees","70 degrees","90 degrees","110 degrees"]},{"id": "8.25-25","std": "8.25","q": "In a figure, parallel lines AB and CD are intersected by two transversals that meet at point E on line CD, forming a triangle. If the angle at A is 52 degrees and the angle at B is 71 degrees, what is the interior angle at E inside the triangle?","a": "57 degrees","lvl": 2,"choices": ["52 degrees","57 degrees","71 degrees","123 degrees"]},{"id": "8.25-26","std": "8.25","q": "Parallel lines j and k are cut by a transversal. Angle A and Angle B are alternate interior angles, and Angle C is supplementary to Angle B. If Angle A = (2x + 34) degrees and Angle C = (3x − 4) degrees, find the measure of Angle B.","a": "94 degrees","lvl": 3,"choices": ["30 degrees","86 degrees","94 degrees","110 degrees"]},{"id": "8.25-27","std": "8.25","q": "Lines L1 and L2 are cut by a transversal. One pair of corresponding angles measures (6x − 12) degrees and (4x + 18) degrees. What must x equal for L1 and L2 to be parallel, and what is the measure of those angles?","a": "x = 15; each angle measures 78 degrees.","lvl": 3,"choices": ["x = 15; each angle measures 78 degrees.","x = 17.4; each angle measures 92.4 degrees.","x = 15; each angle measures 102 degrees.","x = 3; each angle measures 6 degrees."]},{"id": "8.25-28","std": "8.25","q": "A zig-zag path between two parallel walls forms an interior 'elbow' angle pointing left. The top segment makes a 35-degree angle with the top wall, and the bottom segment makes a 42-degree angle with the bottom wall. By drawing an auxiliary parallel line through the vertex of the elbow, find the measure of the acute elbow angle.","a": "77 degrees","lvl": 3,"choices": ["7 degrees","77 degrees","103 degrees","145 degrees"]},{"id": "8.26-09","std": "8.26","q": "In a right triangle, what is the name of the longest side, which is always opposite the right angle?","a": "Hypotenuse","lvl": 1,"choices": ["Leg","Hypotenuse","Base","Transversal"]},{"id": "8.26-10","std": "8.26","q": "Which set of side lengths forms a right triangle?","a": "5, 12, 13","lvl": 1,"choices": ["4, 5, 6","5, 12, 13","6, 7, 8","7, 8, 10"]},{"id": "8.26-11","std": "8.26","q": "A right triangle has squares built on each of its three sides. The areas of the squares on the two legs are 36 square units and 64 square units. What is the area of the square on the hypotenuse?","a": "100 square units","lvl": 1,"choices": ["10 square units","28 square units","100 square units","2,304 square units"]},{"id": "8.26-12","std": "8.26","q": "A triangle has side lengths 11 cm, 60 cm, and 61 cm. Use the converse of the Pythagorean Theorem to determine if it is a right triangle.","a": "Yes, because 11² + 60² = 121 + 3,600 = 3,721, and 61² = 3,721.","lvl": 2,"choices": ["No, because 61 is an odd number.","No, because 11 + 60 is not equal to 61.","Yes, because 61 − 60 = 1.","Yes, because 11² + 60² = 121 + 3,600 = 3,721, and 61² = 3,721."]},{"id": "8.26-13","std": "8.26","q": "A large square with side length (a + b) is divided into 4 congruent right triangles (with legs a, b and hypotenuse c) and a central tilted square of side c. Which algebraic equation comes from equating the total area (a + b)² to the sum of the pieces?","a": "a² + 2ab + b² = 4(0.5ab) + c², which simplifies to a² + b² = c²","lvl": 2,"choices": ["a² + 2ab + b² = 4(0.5ab) + c², which simplifies to a² + b² = c²","a² + b² = 4ab + c²","(a + b)² = c²","a + b = c"]},{"id": "8.26-14","std": "8.26","q": "A triangle has side lengths 10 inches, 15 inches, and 20 inches. Is this a right triangle?","a": "No, because 10² + 15² = 325, which does not equal 20² = 400.","lvl": 2,"choices": ["No, because 20 is divisible by 10.","Yes, because 10 + 15 > 20.","Yes, because the sides increase by 5 each time.","No, because 10² + 15² = 325, which does not equal 20² = 400."]},{"id": "8.26-15","std": "8.26","q": "Two sides of a right triangle measure 8 and 15. Give two different possible values for the third side depending on whether 15 is a leg or the hypotenuse.","a": "17 (if 15 is a leg) or √161 (if 15 is the hypotenuse)","lvl": 3,"choices": ["17 (if 15 is a leg) or √161 (if 15 is the hypotenuse)","17 only, because 15 must be a leg","7 or 17","17 or 23"]},{"id": "8.26-16","std": "8.26","q": "A carpenter builds a triangular frame with sides 18 inches, 24 inches, and 31 inches to make a 90-degree corner. Is the corner exactly 90 degrees? Explain.","a": "No, because 18² + 24² = 900, while 31² = 961; the hypotenuse would need to be 30 inches.","lvl": 3,"choices": ["Yes, because 18 + 24 > 31.","No, because 18² + 24² = 900, while 31² = 961; the hypotenuse would need to be 30 inches.","Yes, because 18, 24, and 31 are close to a 3-4-5 ratio.","No, because 18 + 24 = 42, not 31."]},{"id": "8.26-17","std": "8.26","q": "If a, b, and c form a Pythagorean triple (a² + b² = c²), explain why 3a, 3b, and 3c also form a right triangle.","a": "(3a)² + (3b)² = 9a² + 9b² = 9(a² + b²) = 9c² = (3c)².","lvl": 3,"choices": ["(3a)² + (3b)² = 9a² + 9b² = 9(a² + b²) = 9c² = (3c)².","Multiplying by 3 makes the area 3 times larger.","Adding 3 to each side keeps the angle at 90 degrees.","Any three multiples of 3 form a right triangle."]},{"id": "8.27-09","std": "8.27","q": "Find the distance between the points (−1, 2) and (2, 6) on a coordinate plane.","a": "5 units","lvl": 1,"choices": ["3 units","4 units","5 units","7 units"]},{"id": "8.27-10","std": "8.27","q": "What is the distance between (0, 0) and (8, 15)?","a": "17 units","lvl": 1,"choices": ["7 units","17 units","23 units","289 units"]},{"id": "8.27-11","std": "8.27","q": "To find the distance between (−2, 1) and (3, 13) using the Pythagorean Theorem, what are the lengths of the horizontal and vertical legs of the right triangle?","a": "5 units and 12 units","lvl": 1,"choices": ["1 unit and 12 units","5 units and 12 units","1 unit and 14 units","5 units and 14 units"]},{"id": "8.27-12","std": "8.27","q": "Find the distance between (−4, −3) and (2, 5).","a": "10 units","lvl": 2,"choices": ["6 units","8 units","10 units","14 units"]},{"id": "8.27-13","std": "8.27","q": "Find the exact distance between (1, 5) and (5, 2).","a": "5 units","lvl": 2,"choices": ["3 units","4 units","5 units","7 units"]},{"id": "8.27-14","std": "8.27","q": "On a town map coordinate grid where 1 unit = 1 mile, the library is at (−3, 4) and the park is at (2, −1). To the nearest tenth of a mile, what is the straight-line distance between them?","a": "7.1 miles","lvl": 2,"choices": ["5.0 miles","7.1 miles","10.0 miles","50.0 miles"]},{"id": "8.27-15","std": "8.27","q": "Triangle ABC has vertices A(0, 0), B(6, 0), and C(3, 4). What is the perimeter of Triangle ABC?","a": "16 units","lvl": 3,"choices": ["10 units","14 units","16 units","20 units"]},{"id": "8.27-16","std": "8.27","q": "A drone flies straight from (−5, 8) to (7, 3), and then straight from (7, 3) to (7, −4). What is the total distance the drone flew?","a": "20 units","lvl": 3,"choices": ["13 units","19 units","20 units","25 units"]},{"id": "8.27-17","std": "8.27","q": "Point P is at (2, 1) and Point Q is at (6, y). If the distance between P and Q is 5 units and y > 1, what is the value of y?","a": "4","lvl": 3,"choices": ["2","3","4","5"]},{"id": "8.28-10","std": "8.28","q": "A right triangle has legs of length 9 cm and 12 cm. What is the length of the hypotenuse?","a": "15 cm","lvl": 1,"choices": ["15 cm","21 cm","108 cm","225 cm"]},{"id": "8.28-11","std": "8.28","q": "A right triangle has a hypotenuse of 17 inches and one leg of 8 inches. What is the length of the other leg?","a": "15 inches","lvl": 1,"choices": ["9 inches","15 inches","18.8 inches","25 inches"]},{"id": "8.28-12","std": "8.28","q": "A 13-foot ladder leans against a vertical wall with its base 5 feet from the wall. How high up the wall does the ladder reach?","a": "12 feet","lvl": 1,"choices": ["8 feet","12 feet","13.9 feet","18 feet"]},{"id": "8.28-13","std": "8.28","q": "A rectangular television screen has a width of 48 inches and a height of 27 inches. To the nearest tenth of an inch, what is the diagonal length of the screen?","a": "55.1 inches","lvl": 2,"choices": ["39.7 inches","55.1 inches","75.0 inches","3,033 inches"]},{"id": "8.28-14","std": "8.28","q": "A rectangular park is 90 meters long and 120 meters wide. How many meters shorter is it to walk diagonally across the park than to walk along two edges?","a": "60 meters shorter","lvl": 2,"choices": ["30 meters shorter","60 meters shorter","150 meters shorter","210 meters shorter"]},{"id": "8.28-15","std": "8.28","q": "A guy-wire is attached 15 feet up a telephone pole and anchored to the ground 8 feet from the base of the pole. What is the length of the guy-wire?","a": "17 feet","lvl": 2,"choices": ["7 feet","12.7 feet","17 feet","23 feet"]},{"id": "8.28-16","std": "8.28","q": "An isosceles triangle has two equal sides of length 15 cm and a base of 18 cm. Find the height of the triangle to the base, and then calculate the area of the triangle.","a": "Height = 12 cm, Area = 108 square cm","lvl": 3,"choices": ["Height = 12 cm, Area = 108 square cm","Height = 15 cm, Area = 135 square cm","Height = 12 cm, Area = 216 square cm","Height = 9 cm, Area = 81 square cm"]},{"id": "8.28-17","std": "8.28","q": "A rectangular prism box has a base that is 12 inches by 9 inches, and the box is 8 inches tall. What is the length of the longest straight rod that can fit completely inside the box (from one bottom corner to the opposite top corner)?","a": "17 inches","lvl": 3,"choices": ["15 inches","17 inches","21 inches","29 inches"]},{"id": "8.28-18","std": "8.28","q": "Two joggers start from the same spot. Jogger A runs 4 miles north and 3 miles east. Jogger B runs 5 miles south and 9 miles west. What is the straight-line distance between the two joggers?","a": "15 miles","lvl": 3,"choices": ["12 miles","15 miles","17 miles","21 miles"]},{"id": "8.29-09","std": "8.29","q": "A cone and a cylinder have the exact same base radius and the exact same height. If the volume of the cylinder is 90 cubic centimeters, what is the volume of the cone?","a": "30 cubic centimeters","lvl": 1,"choices": ["30 cubic centimeters","45 cubic centimeters","90 cubic centimeters","270 cubic centimeters"]},{"id": "8.29-10","std": "8.29","q": "How many full cones of water are needed to completely fill a cylinder that has the same radius and height as the cone?","a": "3","lvl": 1,"choices": ["1.5","2","3","4"]},{"id": "8.29-11","std": "8.29","q": "A sphere has radius r, and a cylinder has radius r and height 2r (so the sphere fits snugly inside the cylinder). What fraction of the cylinder's volume does the sphere occupy?","a": "{2/3}","lvl": 1,"choices": ["{2/3}","{1/3}","{3/4}","{1/2}"]},{"id": "8.29-12","std": "8.29","q": "A cone has a volume of 42 cubic inches. What is the volume of a cylinder with the same base area and height?","a": "126 cubic inches","lvl": 2,"choices": ["14 cubic inches","42 cubic inches","84 cubic inches","126 cubic inches"]},{"id": "8.29-13","std": "8.29","q": "A sphere of radius r and a cone of radius r and height 2r are compared. Using the volume formulas, how does the volume of the sphere compare to the volume of this cone?","a": "The sphere's volume is twice the cone's volume.","lvl": 2,"choices": ["The sphere's volume is twice the cone's volume.","The cone's volume is twice the sphere's volume.","They have the exact same volume.","The sphere's volume is three times the cone's volume."]},{"id": "8.29-14","std": "8.29","q": "Since the volume of a cylinder is V = πr²h, how is the formula for the volume of a cone with the same radius and height derived?","a": "Multiply the cylinder's volume by {1/3}, giving V = {1/3}πr²h.","lvl": 2,"choices": ["Divide the cylinder's volume by 2, giving V = {1/2}πr²h.","Subtract πr² from the cylinder's volume.","Multiply the cylinder's volume by {1/3}, giving V = {1/3}πr²h.","Multiply the cylinder's volume by {4/3}, giving V = {4/3}πr²h."]},{"id": "8.29-15","std": "8.29","q": "A solid sphere fits tightly inside a cylinder of radius r and height 2r. If the cylinder's volume is 150π cubic units, what is the volume of the empty space inside the cylinder around the sphere?","a": "50π cubic units","lvl": 3,"choices": ["50π cubic units","75π cubic units","100π cubic units","300π cubic units"]},{"id": "8.29-16","std": "8.29","q": "A cylinder, a sphere, and a cone all have the same radius r. The cylinder and cone both have height 2r. What is the ratio of their volumes (Cone : Sphere : Cylinder)?","a": "1 : 2 : 3","lvl": 3,"choices": ["1 : 2 : 3","1 : 3 : 4","1 : 4 : 3","2 : 3 : 4"]},{"id": "8.29-17","std": "8.29","q": "A cone and a cylinder have the same base radius r. If the cone has 3 times the height of the cylinder, how do their volumes compare?","a": "Their volumes are equal.","lvl": 3,"choices": ["Their volumes are equal.","The cone's volume is 3 times the cylinder's volume.","The cylinder's volume is 3 times the cone's volume.","The cone's volume is {1/9} of the cylinder's volume."]},{"id": "8.30-11","std": "8.30","q": "Find the volume of a cylinder with radius 3 cm and height 10 cm. Leave your answer in terms of π.","a": "90π cubic cm","lvl": 1,"choices": ["30π cubic cm","60π cubic cm","90π cubic cm","300π cubic cm"]},{"id": "8.30-12","std": "8.30","q": "Find the volume of a cone with radius 4 inches and height 9 inches. Leave your answer in terms of π.","a": "48π cubic inches","lvl": 1,"choices": ["12π cubic inches","36π cubic inches","48π cubic inches","144π cubic inches"]},{"id": "8.30-13","std": "8.30","q": "Find the volume of a sphere with radius 6 meters. Leave your answer in terms of π.","a": "288π cubic meters","lvl": 1,"choices": ["48π cubic meters","216π cubic meters","288π cubic meters","864π cubic meters"]},{"id": "8.30-14","std": "8.30","q": "A cylindrical soup can has a diameter of 8 cm and a height of 11 cm. Using 3.14 for π, what is the volume of the can to the nearest tenth?","a": "552.6 cubic cm","lvl": 2,"choices": ["276.3 cubic cm","552.6 cubic cm","1,105.3 cubic cm","2,210.6 cubic cm"]},{"id": "8.30-15","std": "8.30","q": "A traffic cone has a diameter of 12 inches and a height of 18 inches. What is the volume of the cone in terms of π?","a": "216π cubic inches","lvl": 2,"choices": ["72π cubic inches","216π cubic inches","648π cubic inches","864π cubic inches"]},{"id": "8.30-16","std": "8.30","q": "A spherical basketball has a radius of 4.5 inches. Using 3.14 for π, find its volume to the nearest whole cubic inch.","a": "382 cubic inches","lvl": 2,"choices": ["85 cubic inches","254 cubic inches","382 cubic inches","1,145 cubic inches"]},{"id": "8.30-17","std": "8.30","q": "A grain silo is shaped like a cylinder with a hemisphere (half-sphere) on top. Both the cylinder and the hemisphere have a radius of 6 feet, and the cylindrical section is 20 feet tall. What is the total volume of the silo in terms of π?","a": "864π cubic feet","lvl": 3,"choices": ["720π cubic feet","864π cubic feet","936π cubic feet","1,008π cubic feet"]},{"id": "8.30-18","std": "8.30","q": "A cylindrical water tank with radius 5 feet has a volume of 200π cubic feet. What is the height of the tank?","a": "8 feet","lvl": 3,"choices": ["4 feet","8 feet","20 feet","40 feet"]},{"id": "8.30-19","std": "8.30","q": "An ice cream cone has a radius of 2 cm and a height of 9 cm. A single spherical scoop of ice cream also has a radius of 2 cm. If all the ice cream melts into the empty cone, will it overflow? Explain.","a": "No; the sphere's volume is {32/3}π cubic cm, while the cone's volume is 12π = {36/3}π cubic cm, so it fits.","lvl": 3,"choices": ["No; the sphere's volume is {32/3}π cubic cm, while the cone's volume is 12π = {36/3}π cubic cm, so it fits.","No; both shapes have the exact same volume of 12π cubic cm.","Yes; a sphere always has greater volume than a cone with the same radius.","Yes; the sphere has volume 36π cubic cm, which is larger than the cone."]}]};
